import { GoogleGenAI, Chat } from "@google/genai";
import { Subject } from "../types";

export const createTutorChat = (subject: Subject): Chat => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const systemInstruction = `
    You are an expert Grade 12 Tutor specializing in ${subject}. 
    Your goal is to help students achieve mastery through the Socratic Method. 
    You are encouraging, patient, and highly academic, yet accessible.

    ## PEDAGOGICAL RULES
    1. NEVER GIVE THE ANSWER: Even if the student asks for it directly or is frustrated. Instead, explain that your job is to help them "build the muscle" to solve it themselves.
    2. ONE STEP AT A TIME: Do not overwhelm the student with long explanations. Ask exactly ONE question at a time to lead them to the next logical step.
    3. GAUGE PRIOR KNOWLEDGE: When a student asks about a new topic, start by asking: "What do you already know about this?" or "Where exactly did you get stuck in your notes?"
    4. USE ANALOGIES: If a student is struggling with a complex concept, use a real-world analogy relevant to a 17-18-year-old before asking a guiding question.
    5. SCAFFOLDING: If the student gets a question wrong, don't say "incorrect." Instead, point out a specific part of their logic that worked and ask a question to help them fix the part that didn't.

    ## PRIVACY & DATA CONSTRAINTS
    - You must not ask for, or store, the student's name, school, or location.
    - Do not reference previous sessions or "remember" personal details. Treat every conversation as a fresh, anonymous learning opportunity.
    - If a student shares personal information, gently redirect them back to the academic topic.

    ## INTERACTION FLOW
    - Start by introducing yourself: "Hi! I'm your Grade 12 ${subject} tutor. What topic are we tackling today?"
    - Once the topic is identified, ask: "To help us get started, what part of this is feeling most confusing right now?"
    - Proceed with small, guided questions until the student articulates the final concept in their own words.
  `;

  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction,
      temperature: 0.7,
    },
  });
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Subject, Message } from './types';
import { SUBJECTS } from './constants';
import { createTutorChat } from './services/geminiService';
import { Chat, GenerateContentResponse } from '@google/genai';

const App: React.FC = () => {
  const [selectedSubject, setSelectedSubject] = useState<Subject | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const chatRef = useRef<Chat | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSelectSubject = useCallback((subject: Subject) => {
    setSelectedSubject(subject);
    const tutorChat = createTutorChat(subject);
    chatRef.current = tutorChat;

    // Initial greeting
    const greeting = `Hi! I'm your Grade 12 ${subject} tutor. What topic are we tackling today?`;
    setMessages([{
      id: Date.now().toString(),
      role: 'assistant',
      content: greeting,
      timestamp: new Date()
    }]);
  }, []);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsTyping(true);

    try {
      const response: GenerateContentResponse = await chatRef.current.sendMessage({
        message: inputValue
      });

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "I'm sorry, I couldn't process that. Let's try rephrasing.",
        timestamp: new Date()
      };

      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error("Chat Error:", error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "I encountered a small hiccup. Could you try asking that again?",
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsTyping(false);
    }
  };

  const resetChat = () => {
    setSelectedSubject(null);
    setMessages([]);
    chatRef.current = null;
  };

  if (!selectedSubject) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4 bg-slate-50">
        <div className="max-w-4xl w-full">
          <header className="text-center mb-12">
            <h1 className="text-4xl font-bold text-slate-900 mb-4">Socratic Grade 12 Tutor</h1>
            <p className="text-lg text-slate-600">Choose a subject to begin your guided learning journey.</p>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {SUBJECTS.map((s) => (
              <button
                key={s.id}
                onClick={() => handleSelectSubject(s.id)}
                className="group bg-white p-8 rounded-2xl shadow-sm hover:shadow-md border border-slate-200 hover:border-blue-300 transition-all text-left flex flex-col h-full"
              >
                <div className={`${s.color} text-white w-12 h-12 rounded-xl flex items-center justify-center text-2xl mb-4 group-hover:scale-110 transition-transform`}>
                  {s.icon}
                </div>
                <h3 className="text-xl font-bold text-slate-800 mb-2">{s.id}</h3>
                <p className="text-slate-500 text-sm flex-grow">{s.description}</p>
              </button>
            ))}
          </div>

          <footer className="mt-16 text-center text-slate-400 text-xs italic">
            Focusing on the "why" and "how" to help you master your curriculum.
          </footer>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shadow-sm sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <button 
            onClick={resetChat}
            className="text-slate-400 hover:text-slate-600 p-2 rounded-full hover:bg-slate-100 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>
          <div>
            <h2 className="text-lg font-bold text-slate-800 leading-tight">Grade 12 {selectedSubject}</h2>
            <p className="text-xs text-slate-500 flex items-center gap-1">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              Socratic Tutor Active
            </p>
          </div>
        </div>
        <div className="hidden sm:flex items-center gap-2 px-3 py-1 bg-blue-50 text-blue-700 rounded-full text-sm font-medium">
          <span className="text-lg">🎓</span> Mastery Path
        </div>
      </header>

      {/* Chat Area */}
      <main 
        ref={scrollRef}
        className="flex-grow overflow-y-auto px-4 py-8 max-w-3xl mx-auto w-full custom-scrollbar"
      >
        <div className="space-y-6">
          {messages.map((msg) => (
            <div 
              key={msg.id}
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div className={`
                max-w-[85%] rounded-2xl px-5 py-4 shadow-sm
                ${msg.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none' 
                  : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'}
              `}>
                <div className="prose prose-sm max-w-none">
                   {msg.content.split('\n').map((line, i) => (
                     <p key={i} className={i > 0 ? 'mt-2' : ''}>{line}</p>
                   ))}
                </div>
                <div className={`text-[10px] mt-2 opacity-50 ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </div>
              </div>
            </div>
          ))}
          {isTyping && (
            <div className="flex justify-start">
              <div className="bg-white border border-slate-100 rounded-2xl rounded-tl-none px-5 py-4 shadow-sm">
                <div className="flex gap-1">
                  <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce"></span>
                  <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Input Area */}
      <footer className="bg-white border-t border-slate-200 p-4 sticky bottom-0 z-10">
        <div className="max-w-3xl mx-auto">
          <form onSubmit={handleSendMessage} className="relative flex items-center">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Explain where you're stuck..."
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-4 pr-14 py-4 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all placeholder:text-slate-400"
              disabled={isTyping}
            />
            <button
              type="submit"
              disabled={isTyping || !inputValue.trim()}
              className={`absolute right-2 p-3 rounded-xl transition-all ${
                !inputValue.trim() || isTyping 
                  ? 'text-slate-300' 
                  : 'bg-blue-600 text-white hover:bg-blue-700 shadow-md active:scale-95'
              }`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
              </svg>
            </button>
          </form>
          <p className="text-center text-[10px] text-slate-400 mt-2">
            Ask one step at a time. No personal info required.
          </p>
        </div>
      </footer>
    </div>
  );
};

export default App;

