import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { Subject, Level } from "../types";

const getSystemInstruction = (subject: Subject, level: Level) => `
    You are an expert Tutor specializing in the Namibian National Senior Secondary Certificate (NSSC) curriculum.
    You are specifically helping a student with ${subject} at the ${level === 'NSSCAS' ? 'Advanced Subsidiary (AS)' : 'Ordinary (O)'} Level.

    ## PEDAGOGICAL RULES
    1. NEVER GIVE THE ANSWER: Even if the student asks for it directly or is frustrated. Instead, explain that your job is to help them "build the muscle" to solve it themselves.
    2. ONE STEP AT A TIME: Ask exactly ONE question at a time to lead them to the next logical step.
    3. GAUGE PRIOR KNOWLEDGE: Start by asking: "What do you already know about this specific topic in the NSSC syllabus?"
    4. USE ANALOGIES: Use real-world analogies relevant to a 17-18-year-old in Namibia.
    5. SCAFFOLDING: If the student gets a question wrong, point out what worked and ask a guiding question to fix the rest.
    6. RESEARCH: If the student asks for past papers, practice exams, or specific NAMCOL resources, mention you can find them.

    ## PRIVACY & DATA CONSTRAINTS
    - Do not ask for personal info. Treat every conversation as anonymous.

    ## INTERACTION FLOW
    - Start by introducing yourself: "Hi! I'm your NSSC ${level} ${subject} tutor. What part of the syllabus are we tackling today?"
    - Proceed with small, guided questions until the student articulates the final concept in their own words.
`;

export const createTutorChat = (subject: Subject, level: Level) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: getSystemInstruction(subject, level),
      temperature: 0.7,
      tools: [{ googleSearch: {} }]
    },
  });
};

export const connectTutorLive = (
  subject: Subject, 
  level: Level, 
  callbacks: {
    onopen: () => void;
    onmessage: (message: LiveServerMessage) => void;
    onerror: (e: ErrorEvent) => void;
    onclose: (e: CloseEvent) => void;
  }
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  return ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks,
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } },
      },
      systemInstruction: getSystemInstruction(subject, level),
      inputAudioTranscription: {},
      outputAudioTranscription: {},
    },
  });
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Subject, Message, Level, SubjectOption } from './types';
import { SUBJECTS } from './constants';
import { createTutorChat, connectTutorLive } from './services/geminiService';
import { Chat, GenerateContentResponse, LiveServerMessage } from '@google/genai';

// --- Audio Utilities ---
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const App: React.FC = () => {
  const [selectedLevel, setSelectedLevel] = useState<Level | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<SubjectOption | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isVoiceActive, setIsVoiceActive] = useState(false);

  const chatRef = useRef<Chat | null>(null);
  const liveSessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Audio Refs
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Transcription State Refs
  const currentInputTranscription = useRef('');
  const currentOutputTranscription = useRef('');

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isVoiceActive]);

  // Clean up on unmount
  useEffect(() => {
    return () => {
      stopVoiceMode();
    };
  }, []);

  const stopVoiceMode = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.then((s: any) => s.close());
      liveSessionRef.current = null;
    }
    if (inputAudioContextRef.current) {
      inputAudioContextRef.current.close();
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }
    sourcesRef.current.forEach(s => s.stop());
    sourcesRef.current.clear();
    setIsVoiceActive(false);
  };

  const startVoiceMode = async () => {
    if (!selectedSubject) return;
    setIsVoiceActive(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      inputAudioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const sessionPromise = connectTutorLive(selectedSubject.id, selectedSubject.level, {
        onopen: () => {
          const source = inputCtx.createMediaStreamSource(stream);
          const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(inputData.length);
            for (let i = 0; i < inputData.length; i++) {
              int16[i] = inputData[i] * 32768;
            }
            const pcmBlob = {
              data: encode(new Uint8Array(int16.buffer)),
              mimeType: 'audio/pcm;rate=16000',
            };
            sessionPromise.then((session) => {
              session.sendRealtimeInput({ media: pcmBlob });
            });
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputCtx.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          // Handle Audio Playback
          const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (base64Audio && outputAudioContextRef.current) {
            const ctx = outputAudioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }

          // Handle Interruption
          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }

          // Handle Transcriptions
          if (message.serverContent?.inputTranscription) {
            currentInputTranscription.current += message.serverContent.inputTranscription.text;
          }
          if (message.serverContent?.outputTranscription) {
            currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          }

          if (message.serverContent?.turnComplete) {
            const userText = currentInputTranscription.current;
            const assistantText = currentOutputTranscription.current;

            if (userText) {
              setMessages(prev => [...prev, {
                id: `voice-u-${Date.now()}`,
                role: 'user',
                content: userText,
                timestamp: new Date()
              }]);
            }
            if (assistantText) {
              setMessages(prev => [...prev, {
                id: `voice-a-${Date.now()}`,
                role: 'assistant',
                content: assistantText,
                timestamp: new Date()
              }]);
            }

            currentInputTranscription.current = '';
            currentOutputTranscription.current = '';
          }
        },
        onerror: (e) => {
          console.error("Live Error", e);
          stopVoiceMode();
        },
        onclose: () => {
          console.log("Live Closed");
          stopVoiceMode();
        }
      });

      liveSessionRef.current = sessionPromise;
    } catch (err) {
      console.error("Failed to start voice mode", err);
      setIsVoiceActive(false);
    }
  };

  const handleSelectSubject = useCallback((option: SubjectOption) => {
    setSelectedSubject(option);
    const tutorChat = createTutorChat(option.id, option.level);
    chatRef.current = tutorChat;

    const greeting = `Hi! I'm your NSSC ${option.level} ${option.id} tutor. What part of the syllabus are we tackling today?`;
    setMessages([{
      id: Date.now().toString(),
      role: 'assistant',
      content: greeting,
      timestamp: new Date()
    }]);
  }, []);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsTyping(true);

    try {
      const response: GenerateContentResponse = await chatRef.current.sendMessage({
        message: inputValue
      });

      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "I'm sorry, I couldn't process that. Let's try rephrasing.",
        timestamp: new Date(),
        groundingChunks: groundingChunks
      };

      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error("Chat Error:", error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "I encountered a small hiccup. Could you try asking that again?",
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsTyping(false);
    }
  };

  const resetChat = () => {
    stopVoiceMode();
    setSelectedSubject(null);
    setMessages([]);
    chatRef.current = null;
  };

  if (!selectedLevel) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4 bg-slate-50">
        <div className="max-w-4xl w-full text-center">
          <header className="mb-12">
            <h1 className="text-4xl font-bold text-slate-900 mb-4">Namibian NSSC Socratic Tutor</h1>
            <p className="text-lg text-slate-600">Master your syllabus with guided reasoning.</p>
          </header>

          <div className="flex flex-col sm:flex-row gap-6 justify-center">
            <button
              onClick={() => setSelectedLevel('NSSCAS')}
              className="group bg-white p-10 rounded-3xl shadow-sm hover:shadow-xl border border-slate-200 hover:border-blue-400 transition-all w-full sm:w-80"
            >
              <div className="bg-blue-600 text-white w-16 h-16 rounded-2xl flex items-center justify-center text-3xl mx-auto mb-6 group-hover:scale-110 transition-transform">
                A+
              </div>
              <h3 className="text-2xl font-bold text-slate-800 mb-2">NSSCAS</h3>
              <p className="text-slate-500">Advanced Subsidiary Level<br/>(Grade 12)</p>
            </button>
            <button
              onClick={() => setSelectedLevel('NSSCO')}
              className="group bg-white p-10 rounded-3xl shadow-sm hover:shadow-xl border border-slate-200 hover:border-emerald-400 transition-all w-full sm:w-80"
            >
              <div className="bg-emerald-500 text-white w-16 h-16 rounded-2xl flex items-center justify-center text-3xl mx-auto mb-6 group-hover:scale-110 transition-transform">
                O
              </div>
              <h3 className="text-2xl font-bold text-slate-800 mb-2">NSSCO</h3>
              <p className="text-slate-500">Ordinary Level<br/>(Grade 11)</p>
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!selectedSubject) {
    return (
      <div className="min-h-screen p-4 bg-slate-50">
        <div className="max-w-5xl mx-auto py-12">
          <button 
            onClick={() => setSelectedLevel(null)}
            className="mb-8 flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
            </svg>
            Back to Level Selection
          </button>
          <header className="mb-12">
            <h2 className="text-3xl font-bold text-slate-900 mb-2">{selectedLevel} Subjects</h2>
            <p className="text-slate-600">Select your focus area to begin tutoring.</p>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {SUBJECTS.filter(s => s.level === selectedLevel).map((s, idx) => (
              <button
                key={`${s.id}-${idx}`}
                onClick={() => handleSelectSubject(s)}
                className="group bg-white p-8 rounded-2xl shadow-sm hover:shadow-md border border-slate-200 hover:border-blue-300 transition-all text-left flex flex-col h-full"
              >
                <div className={`${s.color} text-white w-12 h-12 rounded-xl flex items-center justify-center text-2xl mb-4 group-hover:scale-110 transition-transform`}>
                  {s.icon}
                </div>
                <h3 className="text-xl font-bold text-slate-800 mb-2">{s.id}</h3>
                <p className="text-slate-500 text-sm flex-grow">{s.description}</p>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shadow-sm sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <button 
            onClick={resetChat}
            className="text-slate-400 hover:text-slate-600 p-2 rounded-full hover:bg-slate-100 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>
          <div>
            <h2 className="text-lg font-bold text-slate-800 leading-tight">{selectedLevel} {selectedSubject.id}</h2>
            <p className="text-xs text-slate-500 flex items-center gap-1">
              <span className={`w-2 h-2 ${isVoiceActive ? 'bg-red-500 animate-pulse' : 'bg-green-500'} rounded-full`}></span>
              {isVoiceActive ? 'Voice Mode Active' : 'Curriculum Expert Online'}
            </p>
          </div>
        </div>
        <div className="hidden sm:flex items-center gap-2 px-3 py-1 bg-blue-50 text-blue-700 rounded-full text-sm font-medium">
          <span className="text-lg">🇳🇦</span> NSSC Syllabus
        </div>
      </header>

      {/* Chat Area */}
      <main 
        ref={scrollRef}
        className="flex-grow overflow-y-auto px-4 py-8 max-w-3xl mx-auto w-full custom-scrollbar"
      >
        <div className="space-y-6">
          {messages.map((msg) => (
            <div 
              key={msg.id}
              className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}
            >
              <div className={`
                max-w-[90%] rounded-2xl px-5 py-4 shadow-sm
                ${msg.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none' 
                  : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'}
              `}>
                <div className="prose prose-sm max-w-none">
                   {msg.content.split('\n').map((line, i) => (
                     <p key={i} className={i > 0 ? 'mt-2' : ''}>{line}</p>
                   ))}
                </div>

                {msg.groundingChunks && msg.groundingChunks.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-slate-100">
                    <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 flex items-center gap-1">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                      </svg>
                      Resources Found:
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {msg.groundingChunks.map((chunk, i) => chunk.web && (
                        <a 
                          key={i} 
                          href={chunk.web.uri} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="text-xs bg-slate-100 hover:bg-slate-200 text-slate-700 px-3 py-1.5 rounded-lg transition-colors flex items-center gap-2 max-w-xs truncate"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                          </svg>
                          {chunk.web.title || chunk.web.uri}
                        </a>
                      ))}
                    </div>
                  </div>
                )}

                <div className={`text-[10px] mt-2 opacity-50 ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </div>
              </div>
            </div>
          ))}
          {(isTyping || (isVoiceActive && messages.length > 0 && messages[messages.length-1].role === 'user')) && (
            <div className="flex justify-start">
              <div className="bg-white border border-slate-100 rounded-2xl rounded-tl-none px-5 py-4 shadow-sm">
                <div className="flex gap-1">
                  <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce"></span>
                  <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Input Area */}
      <footer className="bg-white border-t border-slate-200 p-4 sticky bottom-0 z-10">
        <div className="max-w-3xl mx-auto">
          <div className="flex gap-2">
            <button
              onClick={isVoiceActive ? stopVoiceMode : startVoiceMode}
              className={`p-4 rounded-2xl transition-all shadow-sm flex items-center justify-center ${
                isVoiceActive 
                  ? 'bg-red-500 text-white animate-pulse' 
                  : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
              }`}
              title={isVoiceActive ? "Stop Voice Mode" : "Start Voice Mode"}
            >
              {isVoiceActive ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z" />
                </svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                </svg>
              )}
            </button>

            <form onSubmit={handleSendMessage} className="relative flex-grow flex items-center">
              <input
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder={isVoiceActive ? "Voice mode active... just speak!" : "Ask a question or request NAMCOL papers..."}
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-4 pr-14 py-4 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all placeholder:text-slate-400"
                disabled={isTyping || isVoiceActive}
              />
              <button
                type="submit"
                disabled={isTyping || isVoiceActive || !inputValue.trim()}
                className={`absolute right-2 p-3 rounded-xl transition-all ${
                  !inputValue.trim() || isTyping || isVoiceActive
                    ? 'text-slate-300' 
                    : 'bg-blue-600 text-white hover:bg-blue-700 shadow-md active:scale-95'
                }`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                  <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
                </svg>
              </button>
            </form>
          </div>
          <div className="flex justify-between items-center mt-2 px-1">
            <p className="text-[10px] text-slate-400">
              One step at a time. No personal info required.
            </p>
            <p className="text-[10px] text-slate-400 flex items-center gap-1">
              <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
              NSSC-NA Voice Assistant
            </p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Subject, Message, Level, SubjectOption } from './types';
import { SUBJECTS } from './constants';
import { createTutorChat, connectTutorLive } from './services/geminiService';
import { Chat, GenerateContentResponse, LiveServerMessage } from '@google/genai';

// --- Audio Utilities ---
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const App: React.FC = () => {
  const [selectedLevel, setSelectedLevel] = useState<Level | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<SubjectOption | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isVoiceActive, setIsVoiceActive] = useState(false);

  const chatRef = useRef<Chat | null>(null);
  const liveSessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Audio Refs
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Transcription State Refs
  const currentInputTranscription = useRef('');
  const currentOutputTranscription = useRef('');

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isVoiceActive]);

  useEffect(() => {
    return () => {
      stopVoiceMode();
    };
  }, []);

  const stopVoiceMode = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.then((s: any) => s.close());
      liveSessionRef.current = null;
    }
    if (inputAudioContextRef.current) {
      inputAudioContextRef.current.close();
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }
    sourcesRef.current.forEach(s => s.stop());
    sourcesRef.current.clear();
    setIsVoiceActive(false);
  };

  const startVoiceMode = async () => {
    if (!selectedSubject) return;
    setIsVoiceActive(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      inputAudioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const sessionPromise = connectTutorLive(selectedSubject.id, selectedSubject.level, {
        onopen: () => {
          const source = inputCtx.createMediaStreamSource(stream);
          const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(inputData.length);
            for (let i = 0; i < inputData.length; i++) {
              int16[i] = inputData[i] * 32768;
            }
            const pcmBlob = {
              data: encode(new Uint8Array(int16.buffer)),
              mimeType: 'audio/pcm;rate=16000',
            };
            sessionPromise.then((session) => {
              session.sendRealtimeInput({ media: pcmBlob });
            });
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputCtx.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (base64Audio && outputAudioContextRef.current) {
            const ctx = outputAudioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }

          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }

          if (message.serverContent?.inputTranscription) {
            currentInputTranscription.current += message.serverContent.inputTranscription.text;
          }
          if (message.serverContent?.outputTranscription) {
            currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          }

          if (message.serverContent?.turnComplete) {
            const userText = currentInputTranscription.current;
            const assistantText = currentOutputTranscription.current;

            if (userText) {
              setMessages(prev => [...prev, {
                id: `voice-u-${Date.now()}`,
                role: 'user',
                content: userText,
                timestamp: new Date()
              }]);
            }
            if (assistantText) {
              setMessages(prev => [...prev, {
                id: `voice-a-${Date.now()}`,
                role: 'assistant',
                content: assistantText,
                timestamp: new Date()
              }]);
            }

            currentInputTranscription.current = '';
            currentOutputTranscription.current = '';
          }
        },
        onerror: (e) => {
          console.error("Live Error", e);
          stopVoiceMode();
        },
        onclose: () => {
          stopVoiceMode();
        }
      });

      liveSessionRef.current = sessionPromise;
    } catch (err) {
      console.error("Failed to start voice mode", err);
      setIsVoiceActive(false);
    }
  };

  const handleSelectSubject = useCallback((option: SubjectOption) => {
    setSelectedSubject(option);
    const tutorChat = createTutorChat(option.id, option.level);
    chatRef.current = tutorChat;

    const greeting = `Hi there, future scholar! I'm your NSSC ${option.level} ${option.id} Pocket Tutor. What part of the syllabus are we mastering today?`;
    setMessages([{
      id: Date.now().toString(),
      role: 'assistant',
      content: greeting,
      timestamp: new Date()
    }]);
  }, []);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsTyping(true);

    try {
      const response: GenerateContentResponse = await chatRef.current.sendMessage({
        message: inputValue
      });

      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "I'm sorry, I couldn't process that. Let's try rephrasing.",
        timestamp: new Date(),
        groundingChunks: groundingChunks
      };

      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error("Chat Error:", error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "I encountered a small hiccup. Could you try asking that again?",
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsTyping(false);
    }
  };

  const resetChat = () => {
    stopVoiceMode();
    setSelectedSubject(null);
    setMessages([]);
    chatRef.current = null;
  };

  if (!selectedLevel) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        {/* Background Decals */}
        <div className="absolute top-0 right-0 -translate-y-1/2 translate-x-1/2 w-96 h-96 bg-blue-100 rounded-full blur-3xl opacity-50"></div>
        <div className="absolute bottom-0 left-0 translate-y-1/2 -translate-x-1/2 w-96 h-96 bg-pink-100 rounded-full blur-3xl opacity-50"></div>

        <div className="max-w-4xl w-full text-center relative z-10">
          <header className="mb-14">
            <h1 className="text-5xl md:text-7xl font-black mb-6 tracking-tight leading-none bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 bg-clip-text text-transparent">
              Namibia NSSCO/NSSCAS <br/> Pocket Tutor
            </h1>
            <p className="text-xl md:text-2xl font-bold bg-gradient-to-r from-emerald-500 to-teal-700 bg-clip-text text-transparent max-w-2xl mx-auto">
              Master your syllabus with guided reasoning, <br/> 
              <span className="text-slate-800">join the 1% of the elite students.</span>
            </p>
          </header>

          <div className="flex flex-col sm:flex-row gap-8 justify-center items-stretch">
            <button
              onClick={() => setSelectedLevel('NSSCAS')}
              className="group bg-white p-12 rounded-[2.5rem] shadow-xl hover:shadow-2xl border border-slate-100 hover:border-blue-400 transition-all w-full sm:w-80 flex flex-col items-center"
            >
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-8 group-hover:scale-110 group-hover:rotate-3 transition-transform shadow-lg shadow-blue-200">
                A+
              </div>
              <h3 className="text-3xl font-black text-slate-800 mb-2">NSSCAS</h3>
              <p className="text-slate-500 font-medium">Advanced Subsidiary<br/>Grade 12</p>
              <div className="mt-6 px-4 py-1 rounded-full bg-blue-50 text-blue-600 text-xs font-bold uppercase tracking-widest">Elite Tier</div>
            </button>
            <button
              onClick={() => setSelectedLevel('NSSCO')}
              className="group bg-white p-12 rounded-[2.5rem] shadow-xl hover:shadow-2xl border border-slate-100 hover:border-emerald-400 transition-all w-full sm:w-80 flex flex-col items-center"
            >
              <div className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-8 group-hover:scale-110 group-hover:-rotate-3 transition-transform shadow-lg shadow-emerald-200">
                O
              </div>
              <h3 className="text-3xl font-black text-slate-800 mb-2">NSSCO</h3>
              <p className="text-slate-500 font-medium">Ordinary Level<br/>Grade 11</p>
              <div className="mt-6 px-4 py-1 rounded-full bg-emerald-50 text-emerald-600 text-xs font-bold uppercase tracking-widest">Mastery Tier</div>
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!selectedSubject) {
    return (
      <div className="min-h-screen p-6 bg-slate-50">
        <div className="max-w-5xl mx-auto py-12">
          <button 
            onClick={() => setSelectedLevel(null)}
            className="mb-8 flex items-center gap-2 text-slate-500 hover:text-slate-800 font-bold transition-colors group"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 transform group-hover:-translate-x-1 transition-transform" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
            </svg>
            Switch Level
          </button>
          <header className="mb-12">
            <h2 className="text-4xl font-black text-slate-900 mb-2">{selectedLevel} Specialization</h2>
            <p className="text-slate-600 text-lg">Pick your subject to start building elite reasoning muscles.</p>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {SUBJECTS.filter(s => s.level === selectedLevel).map((s, idx) => (
              <button
                key={`${s.id}-${idx}`}
                onClick={() => handleSelectSubject(s)}
                className="group bg-white p-8 rounded-3xl shadow-md hover:shadow-2xl border border-slate-100 hover:border-blue-400 transition-all text-left flex flex-col h-full relative overflow-hidden"
              >
                <div className="absolute top-0 right-0 w-24 h-24 bg-slate-50 -mr-8 -mt-8 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"></div>
                <div className={`${s.color} text-white w-14 h-14 rounded-2xl flex items-center justify-center text-3xl mb-6 group-hover:scale-110 transition-transform shadow-lg relative z-10`}>
                  {s.icon}
                </div>
                <h3 className="text-2xl font-black text-slate-800 mb-2 relative z-10">{s.id}</h3>
                <p className="text-slate-500 font-medium text-sm flex-grow relative z-10">{s.description}</p>
                <div className="mt-4 flex items-center text-xs font-bold text-blue-600 uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                  Begin Session &rarr;
                </div>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shadow-sm sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <button 
            onClick={resetChat}
            className="text-slate-400 hover:text-slate-600 p-2 rounded-full hover:bg-slate-100 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>
          <div>
            <h2 className="text-lg font-black text-slate-800 leading-tight">
              {selectedLevel} <span className="text-blue-600">{selectedSubject.id}</span>
            </h2>
            <p className="text-xs text-slate-500 flex items-center gap-1">
              <span className={`w-2 h-2 ${isVoiceActive ? 'bg-red-500 animate-pulse' : 'bg-green-500'} rounded-full`}></span>
              {isVoiceActive ? 'Elite Voice Mode' : 'Pocket Tutor Online'}
            </p>
          </div>
        </div>
        <div className="hidden sm:flex items-center gap-2 px-3 py-1 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-100">
          <span className="text-sm">🇳🇦</span> 1% Elite Track
        </div>
      </header>

      {/* Chat Area */}
      <main 
        ref={scrollRef}
        className="flex-grow overflow-y-auto px-4 py-8 max-w-3xl mx-auto w-full custom-scrollbar"
      >
        <div className="space-y-8">
          {messages.map((msg) => (
            <div 
              key={msg.id}
              className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}
            >
              <div className={`
                max-w-[90%] rounded-[2rem] px-6 py-5 shadow-md
                ${msg.role === 'user' 
                  ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white rounded-tr-none' 
                  : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'}
              `}>
                <div className="prose prose-sm max-w-none font-medium leading-relaxed">
                   {msg.content.split('\n').map((line, i) => (
                     <p key={i} className={i > 0 ? 'mt-3' : ''}>{line}</p>
                   ))}
                </div>

                {msg.groundingChunks && msg.groundingChunks.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-slate-100/20">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-1">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                      </svg>
                      Research Intelligence:
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {msg.groundingChunks.map((chunk, i) => chunk.web && (
                        <a 
                          key={i} 
                          href={chunk.web.uri} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="text-[10px] bg-slate-100/50 hover:bg-white text-slate-700 font-bold px-3 py-2 rounded-xl transition-all border border-transparent hover:border-blue-200 flex items-center gap-2 max-w-xs truncate shadow-sm"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 flex-shrink-0 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                          </svg>
                          {chunk.web.title || "External Resource"}
                        </a>
                      ))}
                    </div>
                  </div>
                )}

                <div className={`text-[10px] mt-3 font-bold opacity-60 ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </div>
              </div>
            </div>
          ))}
          {(isTyping || (isVoiceActive && messages.length > 0 && messages[messages.length-1].role === 'user')) && (
            <div className="flex justify-start">
              <div className="bg-white border border-slate-100 rounded-[2rem] rounded-tl-none px-6 py-5 shadow-md">
                <div className="flex gap-2">
                  <span className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></span>
                  <span className="w-2 h-2 bg-purple-500 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-2 h-2 bg-pink-500 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Input Area */}
      <footer className="bg-white border-t border-slate-200 p-6 sticky bottom-0 z-10 shadow-[0_-10px_20px_-10px_rgba(0,0,0,0.05)]">
        <div className="max-w-3xl mx-auto">
          <div className="flex gap-4 items-center">
            <button
