        </div>
      </main>

      <footer className="bg-white border-t border-slate-200 p-6 sticky bottom-0 z-10 shadow-[0_-10px_20px_-10px_rgba(0,0,0,0.05)]">
        <div className="max-w-3xl mx-auto">
          <div className="flex gap-4 items-center">
            <button
              onClick={isVoiceActive ? stopVoiceMode : startVoiceMode}
              className={`p-5 rounded-[1.5rem] transition-all shadow-lg flex items-center justify-center relative overflow-hidden group ${
                isVoiceActive 
                  ? 'bg-red-500 text-white animate-pulse' 
                  : 'bg-gradient-to-br from-slate-800 to-black text-white hover:scale-105 shadow-slate-200'
              }`}
              title={isVoiceActive ? "Close Voice Session" : "Start Voice Session"}
            >
              {isVoiceActive ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                </svg>
              )}
            </button>

            <form onSubmit={handleSendMessage} className="relative flex-grow flex items-center">
              <input
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder={isVoiceActive ? "Listening for your elite insights..." : "Express where you're stuck..."}
                className="w-full bg-slate-50 border border-slate-200 rounded-[1.5rem] pl-6 pr-16 py-5 focus:ring-4 focus:ring-blue-100 focus:border-blue-400 outline-none transition-all placeholder:text-slate-400 font-bold text-slate-700"
                disabled={isTyping || isVoiceActive}
              />
              <button
                type="submit"
                disabled={isTyping || isVoiceActive || !inputValue.trim()}
                className={`absolute right-3 p-3 rounded-xl transition-all ${
                  !inputValue.trim() || isTyping || isVoiceActive
                    ? 'text-slate-300' 
                    : 'bg-blue-600 text-white hover:bg-blue-700 shadow-md active:scale-95'
                }`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                  <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
                </svg>
              </button>
            </form>
          </div>
          <div className="flex justify-between items-center mt-4 px-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              Socratic Mastery Engine
            </p>
            <p className="text-[10px] font-black bg-gradient-to-r from-blue-600 to-pink-500 bg-clip-text text-transparent uppercase tracking-widest flex items-center gap-2">
              <span className="w-1.5 h-1.5 bg-blue-500 rounded-full"></span>
              1% Elite Training
            </p>
          </div>
        </div>
      </footer>
    </div>
  );
};

