import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { Subject, Level } from "../types";

const getSystemInstruction = (subject: Subject, level: Level) => `
    You are an expert Tutor specializing in the Namibian National Senior Secondary Certificate (NSSC) curriculum.
    You are specifically helping a student with ${subject} at the ${level === 'NSSCAS' ? 'Advanced Subsidiary (AS)' : 'Ordinary (O)'} Level.

    ## PEDAGOGICAL RULES
    1. NEVER GIVE THE ANSWER: Even if the student asks for it directly or is frustrated. Instead, explain that your job is to help them "build the muscle" to solve it themselves.
    2. ONE STEP AT A TIME: Ask exactly ONE question at a time to lead them to the next logical step.
    3. GAUGE PRIOR KNOWLEDGE: Start by asking: "What do you already know about this specific topic in the NSSC syllabus?"
    4. USE ANALOGIES: Use real-world analogies relevant to a 17-18-year-old in Namibia.
    5. SCAFFOLDING: If the student gets a question wrong, point out what worked and ask a guiding question to fix the rest.
    6. RESEARCH: If the student asks for past papers, practice exams, or specific NAMCOL resources, mention you can find them.

    ## PRIVACY & DATA CONSTRAINTS
    - Do not ask for personal info. Treat every conversation as anonymous.

    ## INTERACTION FLOW
    - Start by introducing yourself: "Hi! I'm your NSSC ${level} ${subject} tutor. What part of the syllabus are we tackling today?"
    - Proceed with small, guided questions until the student articulates the final concept in their own words.
`;

export const createTutorChat = (subject: Subject, level: Level) => {
  // Use process.env.API_KEY directly for SDK initialization
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: getSystemInstruction(subject, level),
      temperature: 0.7,
      tools: [{ googleSearch: {} }]
    },
  });
};

export const connectTutorLive = (
  subject: Subject, 
  level: Level, 
  callbacks: {
    onopen: () => void;
    onmessage: (message: LiveServerMessage) => void;
    onerror: (e: ErrorEvent) => void;
    onclose: (e: CloseEvent) => void;
  }
) => {
  // Use process.env.API_KEY directly for SDK initialization
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks,
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } },
      },
      systemInstruction: getSystemInstruction(subject, level),
      inputAudioTranscription: {},
      outputAudioTranscription: {},
    },
  });
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Subject, Message, Level, SubjectOption } from './types';
import { SUBJECTS } from './constants';
import { createTutorChat, connectTutorLive } from './services/geminiService';
import { Chat, GenerateContentResponse, LiveServerMessage } from '@google/genai';

// --- Audio Utilities ---
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const App: React.FC = () => {
  const [selectedLevel, setSelectedLevel] = useState<Level | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<SubjectOption | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isVoiceActive, setIsVoiceActive] = useState(false);

  const chatRef = useRef<Chat | null>(null);
  const liveSessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const currentInputTranscription = useRef('');
  const currentOutputTranscription = useRef('');

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isVoiceActive]);

  useEffect(() => {
    return () => {
      stopVoiceMode();
    };
  }, []);

  const stopVoiceMode = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.then((s: any) => s.close());
      liveSessionRef.current = null;
    }
    if (inputAudioContextRef.current) {
      inputAudioContextRef.current.close();
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }
    sourcesRef.current.forEach(s => s.stop());
    sourcesRef.current.clear();
    setIsVoiceActive(false);
  };

  const startVoiceMode = async () => {
    if (!selectedSubject) return;
    setIsVoiceActive(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      inputAudioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const sessionPromise = connectTutorLive(selectedSubject.id, selectedSubject.level, {
        onopen: () => {
          const source = inputCtx.createMediaStreamSource(stream);
          const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(inputData.length);
            for (let i = 0; i < inputData.length; i++) {
              int16[i] = inputData[i] * 32768;
            }
            const pcmBlob = {
              data: encode(new Uint8Array(int16.buffer)),
              mimeType: 'audio/pcm;rate=16000',
            };
            sessionPromise.then((session) => {
              session.sendRealtimeInput({ media: pcmBlob });
            });
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputCtx.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (base64Audio && outputAudioContextRef.current) {
            const ctx = outputAudioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }

          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }

          if (message.serverContent?.inputTranscription) {
            currentInputTranscription.current += message.serverContent.inputTranscription.text;
          }
          if (message.serverContent?.outputTranscription) {
            currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          }

          if (message.serverContent?.turnComplete) {
            const userText = currentInputTranscription.current;
            const assistantText = currentOutputTranscription.current;

            if (userText) {
              setMessages(prev => [...prev, {
                id: `voice-u-${Date.now()}`,
                role: 'user',
                content: userText,
                timestamp: new Date()
              }]);
            }
            if (assistantText) {
              setMessages(prev => [...prev, {
                id: `voice-a-${Date.now()}`,
                role: 'assistant',
                content: assistantText,
                timestamp: new Date()
              }]);
            }

            currentInputTranscription.current = '';
            currentOutputTranscription.current = '';
          }
        },
        onerror: (e) => {
          console.error("Live Error", e);
          stopVoiceMode();
        },
        onclose: () => {
          stopVoiceMode();
        }
      });

      liveSessionRef.current = sessionPromise;
    } catch (err) {
      console.error("Failed to start voice mode", err);
      setIsVoiceActive(false);
    }
  };

  const handleSelectSubject = useCallback((option: SubjectOption) => {
    setSelectedSubject(option);
    const tutorChat = createTutorChat(option.id, option.level);
    chatRef.current = tutorChat;

    const greeting = `Hi there, future scholar! I'm your NSSC ${option.level} ${option.id} Pocket Tutor. What part of the syllabus are we mastering today?`;
    setMessages([{
      id: Date.now().toString(),
      role: 'assistant',
      content: greeting,
      timestamp: new Date()
    }]);
  }, []);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsTyping(true);

    try {
      const response: GenerateContentResponse = await chatRef.current.sendMessage({
        message: inputValue
      });

      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "I'm sorry, I couldn't process that. Let's try rephrasing.",
        timestamp: new Date(),
        groundingChunks: groundingChunks
      };

      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error("Chat Error:", error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "I encountered a small hiccup. Could you try asking that again?",
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsTyping(false);
    }
  };

  const resetChat = () => {
    stopVoiceMode();
    setSelectedSubject(null);
    setMessages([]);
    chatRef.current = null;
    setSearchQuery('');
  };

  // --- Export Functionality ---
  const saveToFile = (filename: string, content: string) => {
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const exportSession = () => {
    if (!selectedSubject || messages.length === 0) return;

    let content = `NSSC POCKET TUTOR SESSION LOG\n`;
    content += `Level: ${selectedLevel}\n`;
    content += `Subject: ${selectedSubject.id}\n`;
    content += `Date: ${new Date().toLocaleString()}\n`;
    content += `------------------------------------------\n\n`;

    messages.forEach(msg => {
      const role = msg.role === 'user' ? 'STUDENT' : 'TUTOR';
      content += `[${msg.timestamp.toLocaleTimeString()}] ${role}:\n${msg.content}\n\n`;
    });

    const filename = `Tutor_Session_${selectedSubject.id}_${Date.now()}.txt`;
    saveToFile(filename, content);
  };

  const saveMessage = (msg: Message) => {
    const role = msg.role === 'user' ? 'Question' : 'Answer';
    const content = `${role} from ${selectedSubject?.id} session (${new Date().toLocaleDateString()}):\n\n${msg.content}`;
    const filename = `Saved_${role}_${Date.now()}.txt`;
    saveToFile(filename, content);
  };

  const filteredSubjects = SUBJECTS.filter(s => 
    s.level === selectedLevel && 
    (searchQuery === '' || s.id.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  if (!selectedLevel) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        <div className="absolute top-0 right-0 -translate-y-1/2 translate-x-1/2 w-96 h-96 bg-blue-100 rounded-full blur-3xl opacity-50"></div>
        <div className="absolute bottom-0 left-0 translate-y-1/2 -translate-x-1/2 w-96 h-96 bg-pink-100 rounded-full blur-3xl opacity-50"></div>

        <div className="max-w-4xl w-full text-center relative z-10">
          <header className="mb-14">
            <h1 className="text-5xl md:text-7xl font-black mb-6 tracking-tight leading-none bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 bg-clip-text text-transparent">
              Namibia NSSCO/NSSCAS <br/> Pocket Tutor
            </h1>
            <p className="text-xl md:text-2xl font-bold bg-gradient-to-r from-emerald-500 to-teal-700 bg-clip-text text-transparent max-w-2xl mx-auto">
              Master your syllabus with guided reasoning, <br/> 
              <span className="text-slate-800">join the 1% of the elite students.</span>
            </p>
          </header>

          <div className="flex flex-col sm:flex-row gap-8 justify-center items-stretch">
            <button
              onClick={() => setSelectedLevel('NSSCAS')}
              className="group bg-white p-12 rounded-[2.5rem] shadow-xl hover:shadow-2xl border border-slate-100 hover:border-blue-400 transition-all w-full sm:w-80 flex flex-col items-center"
            >
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-8 group-hover:scale-110 group-hover:rotate-3 transition-transform shadow-lg shadow-blue-200">
                A+
              </div>
              <h3 className="text-3xl font-black text-slate-800 mb-2">NSSCAS</h3>
              <p className="text-slate-500 font-medium">Advanced Subsidiary<br/>Grade 12</p>
              <div className="mt-6 px-4 py-1 rounded-full bg-blue-50 text-blue-600 text-xs font-bold uppercase tracking-widest">Elite Tier</div>
            </button>
            <button
              onClick={() => setSelectedLevel('NSSCO')}
              className="group bg-white p-12 rounded-[2.5rem] shadow-xl hover:shadow-2xl border border-slate-100 hover:border-emerald-400 transition-all w-full sm:w-80 flex flex-col items-center"
            >
              <div className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-8 group-hover:scale-110 group-hover:-rotate-3 transition-transform shadow-lg shadow-emerald-200">
                O
              </div>
              <h3 className="text-3xl font-black text-slate-800 mb-2">NSSCO</h3>
              <p className="text-slate-500 font-medium">Ordinary Level<br/>Grade 11</p>
              <div className="mt-6 px-4 py-1 rounded-full bg-emerald-50 text-emerald-600 text-xs font-bold uppercase tracking-widest">Mastery Tier</div>
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!selectedSubject) {
    return (
      <div className="min-h-screen p-6 bg-slate-50">
        <div className="max-w-6xl mx-auto py-12">
          <button 
            onClick={() => setSelectedLevel(null)}
            className="mb-8 flex items-center gap-2 text-slate-500 hover:text-slate-800 font-bold transition-colors group"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 transform group-hover:-translate-x-1 transition-transform" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
            </svg>
            Switch Level
          </button>

          <header className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
              <h2 className="text-4xl font-black text-slate-900 mb-2">{selectedLevel} Specialization</h2>
              <p className="text-slate-600 text-lg">Pick your subject to start building elite reasoning muscles.</p>
            </div>

            <div className="relative group w-full md:w-80">
              <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search subjects..."
                className="w-full bg-white border border-slate-200 rounded-2xl pl-12 pr-4 py-4 focus:ring-4 focus:ring-blue-100 focus:border-blue-400 outline-none transition-all font-bold text-slate-700 shadow-sm"
              />
              <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              <div className="absolute right-2 top-1/2 -translate-y-1/2">
                <div className="bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 p-[2px] rounded-xl overflow-hidden shadow-sm">
                  <div className="bg-white px-3 py-1.5 rounded-[10px] text-[10px] font-black uppercase tracking-tighter text-slate-800">Elite Search</div>
                </div>
              </div>
            </div>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredSubjects.map((s, idx) => (
              <button
                key={`${s.id}-${idx}`}
                onClick={() => handleSelectSubject(s)}
                className="group bg-white p-6 rounded-3xl shadow-md hover:shadow-2xl border border-slate-100 hover:border-blue-400 transition-all text-left flex flex-col h-full relative overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300"
                style={{ animationDelay: `${idx * 50}ms` }}
              >
                <div className={`${s.color} text-white w-12 h-12 rounded-2xl flex items-center justify-center text-2xl mb-4 group-hover:scale-110 transition-transform shadow-lg relative z-10`}>
                  {s.icon}
                </div>
                <h3 className="text-xl font-black text-slate-800 mb-1 relative z-10">{s.id}</h3>
                <p className="text-slate-500 font-medium text-xs flex-grow relative z-10 leading-relaxed">{s.description}</p>
                <div className="mt-4 flex items-center text-[10px] font-black text-blue-600 uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                  Begin Session &rarr;
                </div>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shadow-sm sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <button 
            onClick={resetChat}
            className="text-slate-400 hover:text-slate-600 p-2 rounded-full hover:bg-slate-100 transition-colors"
