  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isVoiceActive]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthLoading(true);
    setAuthError(null);
    setAuthSuccess(null);
    try {
      if (authMode === 'signin' || authMode === 'admin') {
        const { data, error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;

        const userEmail = data.user?.email;
        const metadata = data.user?.user_metadata;
        const status = metadata?.status || 'pending';
        const isAdmin = userEmail === MASTER_ADMIN_EMAIL || metadata?.is_admin || false;

        // Restriction check: Only allow admin or approved users
        if (!isAdmin && status !== 'approved') {
          await supabase.auth.signOut();
          throw new Error(status === 'revoked' ? "Your access has been revoked by the administrator." : "Account Pending: Your registration is awaiting administrative approval.");
        }

        if (authMode === 'admin' && !isAdmin) {
          await supabase.auth.signOut();
          throw new Error("Access Denied: You do not have administrative privileges.");
        }

        setAuthSuccess(`Welcome, ${isAdmin ? 'Admin' : 'Achiever'}!`);
      } else {
        // Signup
        const { data, error } = await supabase.auth.signUp({ 
