  const [isTyping, setIsTyping] = useState(false);
  const [isVoiceActive, setIsVoiceActive] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  // Admin State
  const [allUsers, setAllUsers] = useState<any[]>([]);
  const [isAdminView, setIsAdminView] = useState(false);
  const [newAdminEmail, setNewAdminEmail] = useState('');
  const [newAdminPassword, setNewAdminPassword] = useState('');
  const [showNewAdminPassword, setShowNewAdminPassword] = useState(false);

  const chatRef = useRef<Chat | null>(null);
  const liveSessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      handleSession(session);
      setAuthLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      handleSession(session);
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleSession = (session: any) => {
    setSession(session);
    if (session?.user) {
      const metadata = session.user.user_metadata;
      const appUser: AppUser = {
        id: session.user.id,
        email: session.user.email,
        phone_number: metadata.phone_number,
        status: metadata.status || 'pending',
        is_admin: session.user.email === MASTER_ADMIN_EMAIL || metadata.is_admin || false
      };
      setCurrentUser(appUser);

      // If admin, fetch users
      if (appUser.is_admin) {
        fetchUsers();
      }
    } else {
      setCurrentUser(null);
    }
  };

  const fetchUsers = async () => {
    const { data, error } = await supabase.from('profiles').select('*');
    if (!error && data) {
      setAllUsers(data);
    } else {
      // Fallback for demo if profiles table isn't accessible
      setAllUsers([
        { id: '1', email: 'student@example.com', phone_number: '+264 81 234 5678', status: 'pending' },
        { id: '2', email: 'topachiever@school.na', phone_number: '+264 85 999 0000', status: 'approved' },
        { id: 'admin-id', email: MASTER_ADMIN_EMAIL, phone_number: '+264 00 000 0000', status: 'approved' }
      ]);
    }
  };

  const toggleApproval = async (userId: string, currentStatus: UserStatus) => {
    const newStatus = currentStatus === 'approved' ? 'revoked' : 'approved';
    const { error } = await supabase.from('profiles').update({ status: newStatus }).eq('id', userId);
    if (!error) {
      setAllUsers(prev => prev.map(u => u.id === userId ? { ...u, status: newStatus } : u));
    } else {
      // Simulation update
      setAllUsers(prev => prev.map(u => u.id === userId ? { ...u, status: newStatus } : u));
    }
  };

  const updateAdminCredentials = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthLoading(true);
    setAuthError(null);
    setAuthSuccess(null);
    try {
      const updates: any = {};
      if (newAdminEmail) updates.email = newAdminEmail;
      if (newAdminPassword) updates.password = newAdminPassword;

      if (Object.keys(updates).length === 0) return;

      const { error } = await supabase.auth.updateUser(updates);
      if (error) throw error;

      setAuthSuccess("Admin credentials updated successfully!");
      setNewAdminEmail('');
      setNewAdminPassword('');
    } catch (err: any) {
      setAuthError(err.message);
    } finally {
      setAuthLoading(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isVoiceActive]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthLoading(true);
    setAuthError(null);
    setAuthSuccess(null);
    try {
      if (authMode === 'signin' || authMode === 'admin') {
        const { data, error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;

        const userEmail = data.user?.email;
        const metadata = data.user?.user_metadata;
        const status = metadata?.status || 'pending';
        const isAdmin = userEmail === MASTER_ADMIN_EMAIL || metadata?.is_admin || false;

        if (authMode === 'admin' && !isAdmin) {
          await supabase.auth.signOut();
          throw new Error("Access Denied: These are not administrative credentials.");
        }

        if (!isAdmin && status !== 'approved') {
          await supabase.auth.signOut();
          throw new Error(status === 'revoked' ? "Your account access has been revoked." : "Account Pending: Your registration is awaiting admin approval.");
        }

        setAuthSuccess(`Welcome, ${isAdmin ? 'Administrator' : 'Achiever'}!`);
      } else {
        const { data, error } = await supabase.auth.signUp({ 
          email, 
          password,
          options: {
            data: {
              phone_number: phoneNumber,
              status: email === MASTER_ADMIN_EMAIL ? 'approved' : 'pending',
              is_admin: email === MASTER_ADMIN_EMAIL
            }
          }
        });
        if (error) throw error;

        await supabase.from('profiles').insert([
          { id: data.user?.id, email, phone_number: phoneNumber, status: 'pending' }
        ]).catch(() => {});

        setAuthSuccess("Registration successful! Access will be granted once your WhatsApp number is verified and approved by the admin.");
      }
    } catch (err: any) {
      setAuthError(err.message);
    } finally {
      setAuthLoading(false);
    }
  };

  const handleSignOut = async () => {
    await supabase.auth.signOut();
    resetChat();
    setSelectedLevel(null);
    setIsAdminView(false);
  };

  const stopVoiceMode = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.then((s: any) => { try { s.close(); } catch(e) {} });
      liveSessionRef.current = null;
    }
    if (inputAudioContextRef.current) {
      inputAudioContextRef.current.close().catch(() => {});
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close().catch(() => {});
      outputAudioContextRef.current = null;
    }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    setIsVoiceActive(false);
    setStatusMessage(null);
  };

  const startVoiceMode = async () => {
    if (!selectedSubject) return;
    setStatusMessage("Connecting to Socratic engine...");
    setIsVoiceActive(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      await inputCtx.resume();
      await outputCtx.resume();

      inputAudioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const sessionPromise = connectTutorLive(selectedSubject.id, selectedSubject.level, {
        onopen: () => { 
          setStatusMessage(null);
          const source = inputCtx.createMediaStreamSource(stream);
          const processor = inputCtx.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const data = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(data.length);
            for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({
              media: {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000'
              }
            }));
          };
          source.connect(processor);
          processor.connect(inputCtx.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;

          if (base64Audio && outputAudioContextRef.current) {
            const ctx = outputAudioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }

          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }
        },
        onerror: (e) => {
          console.error("Live Connection Error", e);
          stopVoiceMode();
        },
        onclose: () => {
          stopVoiceMode();
        }
      });

      liveSessionRef.current = sessionPromise;
    } catch (err) {
      console.error("Failed to initialize voice session", err);
      setIsVoiceActive(false);
      setStatusMessage("Microphone access required.");
    }
  };

  const handleSelectSubject = useCallback((option: SubjectOption) => {
    setSelectedSubject(option);
    const tutorChat = createChatInstance(option.id, option.level);
    chatRef.current = tutorChat;

    const greeting = `Hi there! I'm your ${option.level} ${option.id} Pocket Tutor. What topic are we tackling today?`;
    setMessages([{
      id: Date.now().toString(),
      role: 'assistant',
      content: greeting,
      timestamp: new Date()
    }]);
  }, []);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsTyping(true);

    try {
      const response: GenerateContentResponse = await chatRef.current.sendMessage({
        message: inputValue
      });

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "I'm sorry, I couldn't process that. Let's try rephrasing.",
        timestamp: new Date(),
        groundingChunks: response.candidates?.[0]?.groundingMetadata?.groundingChunks
      };

      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error("Chat Error:", error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'assistant',
        content: "I encountered a small hiccup. Could you try asking that again?",
        timestamp: new Date()
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const resetChat = () => {
    stopVoiceMode();
    setSelectedSubject(null);
    setMessages([]);
    chatRef.current = null;
    setSearchQuery('');
  };

  const saveToFile = (filename: string, content: string | Blob) => {
    const blob = typeof content === 'string' ? new Blob([content], { type: 'text/plain' }) : content;
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const exportSession = () => {
    if (!selectedSubject || messages.length === 0) return;

    let content = `${selectedLevel} POCKET TUTOR SESSION LOG\n`;
    content += `Subject: ${selectedSubject.id}\n`;
    content += `Date: ${new Date().toLocaleString()}\n`;
    content += `------------------------------------------\n\n`;

    messages.forEach(msg => {
      const role = msg.role === 'user' ? 'STUDENT' : 'TUTOR';
      content += `[${msg.timestamp.toLocaleTimeString()}] ${role}:\n${msg.content}\n\n`;
    });

    const filename = `Tutor_Session_${selectedSubject.id}_${Date.now()}.txt`;
    saveToFile(filename, content);
  };

  const saveMessage = (msg: Message) => {
    const role = msg.role === 'user' ? 'Question' : 'Answer';
    const content = `${role} from ${selectedSubject?.id} session (${new Date().toLocaleDateString()}):\n\n${msg.content}`;
    const filename = `Saved_${role}_${Date.now()}.txt`;
    saveToFile(filename, content);
  };

  const filteredSubjects = SUBJECTS.filter(s => 
