                          <td className="py-5 px-2 font-medium text-slate-400 text-sm">{user.phone_number || 'No number'}</td>
                          <td className="py-5 px-2">
                            <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest ${
                              user.status === 'approved' ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30' :
                              user.status === 'revoked' ? 'bg-red-500/20 text-red-400 border border-red-500/30' :
