                <form onSubmit={updateAdminCredentials} className="space-y-6">
                  <div>
                    <label className="block text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-4">Update Admin Email</label>
                    <input 
                      type="email" 
                      value={newAdminEmail}
                      onChange={(e) => setNewAdminEmail(e.target.value)}
                      className="w-full bg-slate-800/50 border border-slate-700 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-blue-500/20 outline-none transition-all font-bold text-white text-sm"
