                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" />
                          </svg>
                        ) : (
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268-2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                          </svg>
                        )}
                      </button>
                    </div>
                  </div>
                  {authSuccess && <div className="text-emerald-400 text-[10px] font-black text-center">{authSuccess}</div>}
                  <button type="submit" className="w-full bg-gradient-to-r from-blue-600 to-purple-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-500/20 hover:scale-[1.02] active:scale-[0.98] transition-all uppercase tracking-widest text-xs">Update Admin Access</button>
                </form>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Auth Screen
  if (!session) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        <div className="absolute top-0 right-0 -translate-y-1/2 translate-x-1/2 w-[500px] h-[500px] bg-blue-100 rounded-full blur-[120px] opacity-60"></div>
        <div className="absolute bottom-0 left-0 translate-y-1/2 -translate-x-1/2 w-[500px] h-[500px] bg-pink-100 rounded-full blur-[120px] opacity-60"></div>
        <div className="max-w-md w-full relative z-10">
          <div className="text-center mb-10">
            <h1 className="text-4xl md:text-5xl font-black mb-4 tracking-tighter leading-none bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 bg-clip-text text-transparent">Top 1% Achievers <br/> Portal</h1>
            <p className="text-slate-500 font-bold text-sm uppercase tracking-widest">{authMode === 'admin' ? 'Admin Gateway' : 'NSSCO / NSSCAS Mastery Hub'}</p>
          </div>
          <div className="bg-white/80 backdrop-blur-xl p-8 rounded-[2.5rem] shadow-2xl border border-white/50">
            <form onSubmit={handleAuth} className="space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-4">Account Email</label>
                <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-blue-100 outline-none transition-all font-bold text-slate-700" placeholder="name@school.edu.na" required />
              </div>
              {authMode === 'signup' && (
                <div className="animate-in fade-in slide-in-from-top-2">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-4">WhatsApp / Cell</label>
                  <input type="tel" value={phoneNumber} onChange={(e) => setPhoneNumber(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-blue-100 outline-none transition-all font-bold text-slate-700" placeholder="+264 81..." required />
                </div>
              )}
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-4">Mastery Key</label>
                <div className="relative">
                  <input type={showPassword ? "text" : "password"} value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-blue-100 outline-none transition-all font-bold text-slate-700 pr-14" placeholder="••••••••" required />
                  <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 p-2 text-slate-400 hover:text-blue-600 transition-colors">
                    {showPassword ? <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg> : <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268-2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>}
                  </button>
                </div>
              </div>
              {authError && <div className="bg-red-50 text-red-600 p-4 rounded-xl text-xs font-bold border border-red-100 leading-tight">{authError}</div>}
              {authSuccess && <div className="bg-emerald-50 text-emerald-600 p-4 rounded-xl text-xs font-bold border border-emerald-100">{authSuccess}</div>}
              <button type="submit" disabled={authLoading} className="w-full bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 text-white font-black py-5 rounded-2xl shadow-xl shadow-blue-200 hover:scale-[1.02] active:scale-[0.98] transition-all uppercase tracking-widest disabled:opacity-50">
                {authLoading ? 'Authorizing...' : (authMode === 'signin' ? 'Unlock Academy' : (authMode === 'admin' ? 'Enter Management' : 'Register Profile'))}
              </button>
            </form>
            <div className="mt-8 pt-8 border-t border-slate-100 text-center space-y-4">
              <button onClick={() => { setAuthMode(authMode === 'signin' ? 'signup' : 'signin'); setAuthError(null); setAuthSuccess(null); }} className="text-xs font-black text-slate-500 hover:text-blue-600 uppercase tracking-widest transition-colors block w-full">{authMode === 'signin' ? "Need a Profile? Sign Up" : "Back to Sign In"}</button>
              <button onClick={() => { setAuthMode(authMode === 'admin' ? 'signin' : 'admin'); setAuthError(null); setAuthSuccess(null); }} className="text-[9px] font-black text-slate-400 hover:text-slate-800 uppercase tracking-[0.2em] transition-colors">{authMode === 'admin' ? "Student Portal" : "Admin Gateway"}</button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Regular App View
  if (!selectedLevel) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        {currentUser?.is_admin && (
          <button onClick={() => setIsAdminView(true)} className="absolute top-8 left-8 bg-slate-900 text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:scale-105 transition-all z-50 flex items-center gap-3 border border-white/10">
            <span className="w-2 h-2 bg-emerald-400 rounded-full animate-pulse"></span>
            Admin Console
          </button>
        )}
        <div className="max-w-4xl w-full text-center relative z-10">
          <header className="mb-14">
            <div className="flex justify-center mb-6"><button onClick={handleSignOut} className="bg-white px-6 py-2 rounded-full shadow-sm text-[10px] font-black text-slate-400 hover:text-red-500 transition-colors uppercase tracking-widest border border-slate-100">Sign Out</button></div>
            <h1 className="text-5xl md:text-7xl font-black mb-6 tracking-tight leading-none bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 bg-clip-text text-transparent">Namibia NSSCO/NSSCAS <br/> Pocket Tutor</h1>
            <p className="text-xl md:text-2xl font-bold bg-gradient-to-r from-emerald-500 to-teal-700 bg-clip-text text-transparent max-w-2xl mx-auto">Master your syllabus with guided reasoning. <br/><span className="text-slate-800">Become a Top 1% Achiever.</span></p>
