            <button onClick={() => setSelectedLevel('NSSCAS')} className="group bg-white p-12 rounded-[2.5rem] shadow-xl hover:shadow-2xl border border-slate-100 transition-all w-full sm:w-80 flex flex-col items-center">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-8 group-hover:scale-110 transition-transform">AS</div>
              <h3 className="text-3xl font-black text-slate-800 mb-2">NSSCAS</h3>
              <p className="text-slate-500 font-medium text-sm leading-relaxed">Advanced Grade 12</p>
            </button>
            <button onClick={() => setSelectedLevel('NSSCO')} className="group bg-white p-12 rounded-[2.5rem] shadow-xl hover:shadow-2xl border border-slate-100 transition-all w-full sm:w-80 flex flex-col items-center">
              <div className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-8 group-hover:scale-110 transition-transform">O</div>
              <h3 className="text-3xl font-black text-slate-800 mb-2">NSSCO</h3>
              <p className="text-slate-500 font-medium text-sm leading-relaxed">Ordinary Grade 10-11</p>
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!selectedSubject) {
    return (
      <div className="min-h-screen p-6 bg-slate-50">
        <div className="max-w-6xl mx-auto py-12">
          <div className="flex items-center justify-between mb-8">
            <button onClick={() => setSelectedLevel(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 font-bold transition-colors group">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 transform group-hover:-translate-x-1 transition-transform" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
              Level Select
            </button>
            <button onClick={handleSignOut} className="text-[10px] font-black text-slate-400 hover:text-red-500 transition-colors uppercase tracking-widest">Sign Out</button>
          </div>
          <header className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
              <h2 className="text-4xl font-black text-slate-900 mb-2">{selectedLevel} Subjects</h2>
              <p className="text-slate-600 text-lg">Pick a subject to join the Top 1%.</p>
            </div>
            <div className="relative w-full md:w-80">
              <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search..." className="w-full bg-white border border-slate-200 rounded-2xl pl-12 pr-4 py-4 focus:ring-4 focus:ring-blue-100 outline-none font-bold text-slate-700 shadow-sm" />
              <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></div>
            </div>
          </header>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {filteredSubjects.map((s, idx) => (
              <button key={`${s.id}-${idx}`} onClick={() => handleSelectSubject(s)} className="group bg-white p-6 rounded-3xl shadow-md hover:shadow-2xl border border-slate-100 transition-all text-left flex flex-col relative overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300" style={{ animationDelay: `${idx * 50}ms` }}>
                <div className={`${s.color} text-white w-12 h-12 rounded-2xl flex items-center justify-center text-2xl mb-4 group-hover:scale-110 transition-transform shadow-lg`}>{s.icon}</div>
                <h3 className="text-xl font-black text-slate-800 mb-1">{s.id}</h3>
                <p className="text-slate-500 font-medium text-xs flex-grow leading-relaxed">{s.description}</p>
                <div className="mt-4 text-[10px] font-black text-blue-600 uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">Launch &rarr;</div>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
