          <button onClick={resetChat} className="text-slate-400 hover:text-slate-600 p-2 rounded-full hover:bg-slate-100 transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg></button>
          <div><h2 className="text-lg font-black text-slate-800 leading-tight">{selectedLevel} <span className="text-blue-600">{selectedSubject.id}</span></h2><p className="text-xs text-slate-500 flex items-center gap-1"><span className={`w-2 h-2 ${isVoiceActive ? 'bg-red-500 animate-pulse' : 'bg-green-500'} rounded-full`}></span>{isVoiceActive ? 'Voice Interaction' : 'Online'}</p></div>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex flex-col items-end text-right max-w-[280px]">
            <span className="text-[10px] font-black uppercase tracking-tighter bg-gradient-to-r from-blue-600 via-purple-600 via-pink-500 via-orange-500 via-green-600 to-blue-600 bg-clip-text text-transparent leading-tight text-center">
              use your device audio recorder to record and listen when offline
            </span>
          </div>
          {messages.length > 0 && (
            <button onClick={exportSession} className="bg-white border-2 border-slate-100 hover:border-blue-200 text-slate-700 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 transition-all hover:shadow-md active:scale-95 group">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-blue-600 group-hover:animate-bounce" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              Export
            </button>
          )}
        </div>
      </header>

      <main ref={scrollRef} className="flex-grow overflow-y-auto px-4 py-8 max-w-3xl mx-auto w-full custom-scrollbar">
        <div className="space-y-8">
          {statusMessage && <div className="bg-blue-50 text-blue-700 px-4 py-3 rounded-2xl text-xs font-bold text-center border border-blue-100 animate-pulse">{statusMessage}</div>}
          {messages.length === 0 && !isVoiceActive && (
             <div className="text-center py-20">
                <div className="bg-blue-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-3xl shadow-inner">🎓</div>
                <h3 className="text-xl font-black text-slate-800 mb-2">Ready for {selectedSubject.id}?</h3>
                <p className="text-slate-500 text-sm max-w-sm mx-auto">Start a text dialogue below or tap the mic for a Socratic session.</p>
             </div>
          )}
          {messages.map((msg) => (
            <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} group animate-in fade-in slide-in-from-bottom-2`}>
              <div className={`max-w-[90%] rounded-[2rem] px-6 py-5 shadow-md relative ${msg.role === 'user' ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white rounded-tr-none' : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'}`}>
                <div className="prose prose-sm max-w-none font-medium leading-relaxed">{msg.content.split('\n').map((line, i) => (<p key={i} className={i > 0 ? 'mt-3' : ''}>{line}</p>))}</div>
                <div className="flex items-center justify-between mt-3"><div className="text-[9px] font-bold opacity-60">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div></div>
              </div>
            </div>
          ))}
          {isTyping && <div className="flex justify-start"><div className="bg-white border border-slate-100 rounded-[2rem] rounded-tl-none px-6 py-5 shadow-md"><div className="flex gap-2"><span className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></span><span className="w-2 h-2 bg-purple-500 rounded-full animate-bounce [animation-delay:0.2s]"></span><span className="w-2 h-2 bg-pink-500 rounded-full animate-bounce [animation-delay:0.4s]"></span></div></div></div>}
          {isVoiceActive && !statusMessage && (
            <div className="text-center py-6 animate-in fade-in zoom-in">
              <div className="inline-flex flex-col items-center">
                 <div className="relative mb-4"><div className="absolute inset-0 bg-blue-400 rounded-full animate-ping opacity-20"></div><div className="bg-blue-600 p-6 rounded-full text-white shadow-xl shadow-blue-200 relative"><svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></div></div>
                 <h4 className="font-black text-slate-800 text-xs uppercase tracking-widest">Socratic Stream Active</h4>
                 <p className="text-slate-400 text-[9px] font-bold mt-1">Guided reasoning via audio stream.</p>
              </div>
            </div>
          )}
        </div>
      </main>

      <footer className="bg-white border-t border-slate-200 p-6 sticky bottom-0 z-10">
        <div className="max-w-3xl mx-auto">
          <div className="flex gap-4 items-center">
            <button onClick={isVoiceActive ? stopVoiceMode : startVoiceMode} className={`p-5 rounded-[1.5rem] transition-all shadow-lg flex items-center justify-center ${isVoiceActive ? 'bg-red-500 text-white animate-pulse' : 'bg-slate-900 text-white hover:scale-105 active:scale-95'}`}>
              {isVoiceActive ? <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg> : <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>}
            </button>
