    );
  }

  // Subject Selection
  if (!selectedSubject) {
    return (
      <div className="min-h-screen p-6 bg-slate-50">
        <div className="max-w-6xl mx-auto py-12">
          <div className="flex items-center justify-between mb-8">
            <button onClick={() => setSelectedLevel(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 font-bold transition-colors group">
