            </div>
          </header>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {filteredSubjects.map((s, idx) => (
              <button key={`${s.id}-${idx}`} onClick={() => handleSelectSubject(s)} className="group bg-white p-6 rounded-3xl shadow-md hover:shadow-2xl border border-slate-100 transition-all text-left flex flex-col relative overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300" style={{ animationDelay: `${idx * 50}ms` }}>
                <div className={`${s.color} text-white w-12 h-12 rounded-2xl flex items-center justify-center text-2xl mb-4 group-hover:scale-110 transition-transform shadow-lg`}>{s.icon}</div>
