          <div><h2 className="text-lg font-black text-slate-800 leading-tight">{selectedLevel} <span className="text-blue-600">{selectedSubject.id}</span></h2><p className="text-xs text-slate-500 flex items-center gap-1"><span className={`w-2 h-2 ${isVoiceActive ? 'bg-red-500 animate-pulse' : 'bg-green-500'} rounded-full`}></span>{isVoiceActive ? 'Voice Interaction Live' : 'Pocket Tutor Online'}</p></div>
