          {messages.length === 0 && !isVoiceActive && (
             <div className="text-center py-20">
                <div className="bg-blue-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-3xl shadow-inner">🎓</div>
                <h3 className="text-xl font-black text-slate-800 mb-2">Mastering {selectedSubject.id}</h3>
                <p className="text-slate-500 text-sm max-w-sm mx-auto">Start our Socratic dialogue below or tap the mic for a voice session.</p>
             </div>
          )}
          {messages.map((msg) => (
            <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} group animate-in fade-in slide-in-from-bottom-2`}>
              <div className={`max-w-[90%] rounded-[2rem] px-6 py-5 shadow-md relative ${msg.role === 'user' ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white rounded-tr-none' : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'}`}>
                <div className="prose prose-sm max-w-none font-medium leading-relaxed">{msg.content.split('\n').map((line, i) => (<p key={i} className={i > 0 ? 'mt-3' : ''}>{line}</p>))}</div>
                <div className="flex items-center justify-between mt-3"><div className="text-[9px] font-bold opacity-60">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div></div>
              </div>
            </div>
          ))}
          {isTyping && <div className="flex justify-start"><div className="bg-white border border-slate-100 rounded-[2rem] rounded-tl-none px-6 py-5 shadow-md"><div className="flex gap-2"><span className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></span><span className="w-2 h-2 bg-purple-500 rounded-full animate-bounce [animation-delay:0.2s]"></span><span className="w-2 h-2 bg-pink-500 rounded-full animate-bounce [animation-delay:0.4s]"></span></div></div></div>}
          {isVoiceActive && !statusMessage && (
            <div className="text-center py-6 animate-in fade-in zoom-in">
              <div className="inline-flex flex-col items-center">
                 <div className="relative mb-4"><div className="absolute inset-0 bg-blue-400 rounded-full animate-ping opacity-20"></div><div className="bg-blue-600 p-6 rounded-full text-white shadow-xl shadow-blue-200 relative"><svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></div></div>
                 <h4 className="font-black text-slate-800 text-xs uppercase tracking-widest">Guided Audio Active</h4>
                 <p className="text-slate-400 text-[9px] font-bold mt-1">Guided reasoning via audio stream.</p>
              </div>
            </div>
          )}
        </div>
      </main>

      <footer className="bg-white border-t border-slate-200 p-6 sticky bottom-0 z-10">
        <div className="max-w-3xl mx-auto">
          <div className="flex gap-4 items-center">
            <button onClick={isVoiceActive ? stopVoiceMode : startVoiceMode} className={`p-5 rounded-[1.5rem] transition-all shadow-lg flex items-center justify-center ${isVoiceActive ? 'bg-red-500 text-white animate-pulse' : 'bg-slate-900 text-white hover:scale-105 active:scale-95'}`}>
              {isVoiceActive ? <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg> : <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>}
            </button>
            <form onSubmit={handleSendMessage} className="relative flex-grow flex items-center">
              <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} placeholder={isVoiceActive ? "Listening to your thoughts..." : "How can I guide you today?"} className="w-full bg-slate-50 border border-slate-200 rounded-[1.5rem] pl-6 pr-16 py-5 focus:ring-4 focus:ring-blue-100 outline-none font-bold text-slate-700" disabled={isTyping || isVoiceActive} />
              <button type="submit" disabled={isTyping || isVoiceActive || !inputValue.trim()} className={`absolute right-3 p-3 rounded-xl transition-all ${!inputValue.trim() || isTyping || isVoiceActive ? 'text-slate-300' : 'bg-blue-600 text-white shadow-md active:scale-95'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg></button>
            </form>
          </div>
          <div className="flex justify-between items-center mt-4 px-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Socratic Mastery 🎓</p>
            <p className="text-[10px] font-black bg-gradient-to-r from-blue-600 to-pink-500 bg-clip-text text-transparent uppercase tracking-widest">Top 1% Achiever 🇳🇦</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Message, Level, SubjectOption } from './types';
import { SUBJECTS } from './constants';
import { createChatInstance, connectTutorLive } from './services/geminiService';
import { Chat, GenerateContentResponse, LiveServerMessage } from '@google/genai';

// --- Audio Utilities ---
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const App: React.FC = () => {
  // App State
  const [selectedLevel, setSelectedLevel] = useState<Level | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<SubjectOption | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isVoiceActive, setIsVoiceActive] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  const chatRef = useRef<Chat | null>(null);
  const liveSessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isVoiceActive]);

  const stopVoiceMode = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.then((s: any) => { try { s.close(); } catch(e) {} });
      liveSessionRef.current = null;
    }
    if (inputAudioContextRef.current) {
      inputAudioContextRef.current.close().catch(() => {});
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close().catch(() => {});
      outputAudioContextRef.current = null;
    }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    setIsVoiceActive(false);
    setStatusMessage(null);
  };

  const startVoiceMode = async () => {
    if (!selectedSubject) return;
    setStatusMessage("Connecting to Socratic Audio Stream...");
    setIsVoiceActive(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      await inputCtx.resume();
      await outputCtx.resume();
      inputAudioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const sessionPromise = connectTutorLive(selectedSubject.id, selectedSubject.level, {
        onopen: () => { 
          setStatusMessage(null);
          const source = inputCtx.createMediaStreamSource(stream);
          const processor = inputCtx.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const data = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(data.length);
            for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({
              media: {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000'
              }
            }));
          };
          source.connect(processor);
          processor.connect(inputCtx.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (base64Audio && outputAudioContextRef.current) {
            const ctx = outputAudioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }
          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }
        },
        onerror: (e) => { console.error(e); stopVoiceMode(); },
        onclose: () => stopVoiceMode()
      });
      liveSessionRef.current = sessionPromise;
    } catch (err) {
      setIsVoiceActive(false);
      setStatusMessage("Microphone required for voice tutoring.");
    }
  };

  const handleSelectSubject = useCallback((option: SubjectOption) => {
    setSelectedSubject(option);
    const tutorChat = createChatInstance(option.id, option.level);
    chatRef.current = tutorChat;
    const greeting = `Greetings! I am your ${option.level} ${option.id} Pocket Tutor. What topic shall we explore today?`;
    setMessages([{ id: Date.now().toString(), role: 'assistant', content: greeting, timestamp: new Date() }]);
  }, []);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;
