      const sessionPromise = connectTutorLive(selectedSubject.id, selectedSubject.level, {
        onopen: () => { 
          setStatusMessage(null);
          const source = inputCtx.createMediaStreamSource(stream);
          const processor = inputCtx.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const data = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(data.length);
            for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({
              media: {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000'
              }
            }));
          };
          source.connect(processor);
          processor.connect(inputCtx.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (base64Audio && outputAudioContextRef.current) {
            const ctx = outputAudioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }
          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }
        },
        onerror: (e) => { console.error(e); stopVoiceMode(); },
        onclose: () => stopVoiceMode()
      });
      liveSessionRef.current = sessionPromise;
    } catch (err) {
      setIsVoiceActive(false);
      setStatusMessage("Microphone required for voice tutoring.");
    }
  };

  const handleSelectSubject = useCallback((option: SubjectOption) => {
    setSelectedSubject(option);
    const tutorChat = createChatInstance(option.id, option.level);
    chatRef.current = tutorChat;
    const greeting = `Greetings, ${currentUser?.name}! I am your ${option.level} ${option.id} Pocket Tutor. What shall we solve today?`;
    setMessages([{ id: Date.now().toString(), role: 'assistant', content: greeting, timestamp: new Date() }]);
  }, [currentUser]);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;
    const userMessage: Message = { id: Date.now().toString(), role: 'user', content: inputValue, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsTyping(true);
    try {
      const response: GenerateContentResponse = await chatRef.current.sendMessage({ message: inputValue });
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "I'm contemplating your query. Could you elaborate slightly?",
        timestamp: new Date(),
        groundingChunks: response.candidates?.[0]?.groundingMetadata?.groundingChunks
      };
      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'assistant', content: "An unexpected error occurred. Let's try again.", timestamp: new Date() }]);
    } finally { setIsTyping(false); }
  };

  const resetChat = () => {
    stopVoiceMode();
    setSelectedSubject(null);
    setMessages([]);
    chatRef.current = null;
  };

  const exportSession = () => {
    if (!selectedSubject || messages.length === 0) return;
    let content = `POCKET TUTOR SESSION LOG\nLevel: ${selectedLevel}\nSubject: ${selectedSubject.id}\nStudent: ${currentUser?.name}\nTime: ${new Date().toLocaleString()}\n\n`;
    messages.forEach(msg => { content += `[${msg.role === 'user' ? 'STUDENT' : 'TUTOR'}]: ${msg.content}\n\n`; });
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Session_${selectedSubject.id}_${Date.now()}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const filteredSubjects = SUBJECTS.filter(s => s.level === selectedLevel && (searchQuery === '' || s.id.toLowerCase().includes(searchQuery.toLowerCase())));

  // --- VIEWS ---

  // Admin Management View
  if (currentUser?.isAdmin && isAdminPanelOpen) {
    return (
      <div className="min-h-screen bg-slate-900 text-white p-8">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-center mb-12">
            <div>
              <h1 className="text-4xl font-black tracking-tight">Management Panel</h1>
              <p className="text-slate-400">Manage student access and registrations</p>
            </div>
            <div className="flex gap-4">
              <button onClick={() => setIsAdminPanelOpen(false)} className="bg-slate-800 px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-slate-700 transition-colors">Tutoring App</button>
              <button onClick={logout} className="bg-red-500/10 text-red-500 px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-red-500 hover:text-white transition-colors">Logout</button>
            </div>
          </header>

          <div className="bg-slate-800 rounded-3xl border border-slate-700 overflow-hidden shadow-2xl">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-800/50 text-slate-500 text-[10px] font-black uppercase tracking-widest border-b border-slate-700">
                  <th className="px-8 py-6">Name</th>
                  <th className="px-8 py-6">Phone Number</th>
                  <th className="px-8 py-6">Access Status</th>
                  <th className="px-8 py-6 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-700">
                {allUsers.length === 0 ? (
                  <tr><td colSpan={4} className="px-8 py-12 text-center text-slate-500 font-bold">No students registered yet.</td></tr>
                ) : (
                  allUsers.map(user => (
                    <tr key={user.id} className="hover:bg-slate-700/50 transition-colors">
                      <td className="px-8 py-6 font-bold">{user.name}</td>
                      <td className="px-8 py-6 text-slate-400">{user.phone}</td>
                      <td className="px-8 py-6">
                        <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                          user.status === 'approved' ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30' :
                          user.status === 'revoked' ? 'bg-red-500/20 text-red-400 border border-red-500/30' :
                          'bg-amber-500/20 text-amber-400 border border-amber-500/30'
                        }`}>
                          {user.status}
                        </span>
                      </td>
                      <td className="px-8 py-6 text-right">
                        <div className="flex justify-end gap-3">
                          {user.status !== 'approved' && (
                            <button onClick={() => setStatus(user.id, 'approved')} className="bg-emerald-500 text-white px-4 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-emerald-600 transition-colors">Approve</button>
                          )}
                          {user.status !== 'revoked' && (
                            <button onClick={() => setStatus(user.id, 'revoked')} className="bg-red-500/10 text-red-500 px-4 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-red-500 hover:text-white transition-colors">Revoke</button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }

  // --- Login / Sign Up Screens ---
  if (!currentUser) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        <div className="absolute top-0 right-0 -translate-y-1/2 translate-x-1/2 w-96 h-96 bg-blue-100 rounded-full blur-3xl opacity-50"></div>
        <div className="absolute bottom-0 left-0 translate-y-1/2 -translate-x-1/2 w-96 h-96 bg-pink-100 rounded-full blur-3xl opacity-50"></div>

        <div className="max-w-md w-full relative z-10">
          <div className="text-center mb-10">
            <h1 className="text-4xl font-black mb-2 tracking-tight bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
              {authView === 'login' ? 'Welcome Back' : authView === 'signup' ? 'Join Academy' : 'Management Portal'}
            </h1>
            <p className="text-slate-500 font-bold text-sm uppercase tracking-widest">NSSCO / NSSCAS Mastery Hub</p>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] shadow-2xl border border-slate-100">
            {authSuccess && <div className="bg-emerald-50 text-emerald-700 p-4 rounded-2xl text-xs font-bold mb-6 border border-emerald-100">{authSuccess}</div>}
            {authError && <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-xs font-bold mb-6 border border-red-100">{authError}</div>}

            <form onSubmit={authView === 'login' ? handleLogin : authView === 'signup' ? handleSignUp : handleAdminLogin} className="space-y-5">
              {authView === 'signup' && (
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-4">Full Name</label>
                  <input type="text" value={nameField} onChange={(e) => setNameField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-blue-100 outline-none font-bold text-slate-700" placeholder="Student Name" />
                </div>
              )}
              {authView === 'admin_login' ? (
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-4">Admin Email</label>
                  <input type="email" value={emailField} onChange={(e) => setEmailField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-blue-100 outline-none font-bold text-slate-700" placeholder="pemo...@gmail.com" />
                </div>
              ) : (
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-4">Phone Number</label>
                  <input type="tel" value={phoneField} onChange={(e) => setPhoneField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-blue-100 outline-none font-bold text-slate-700" placeholder="+264 ..." />
                </div>
              )}
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-4">Mastery Key</label>
                <input type="password" value={passwordField} onChange={(e) => setPasswordField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-blue-100 outline-none font-bold text-slate-700" placeholder="••••••••" />
              </div>

              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all uppercase tracking-widest text-xs mt-4">
                {authView === 'login' ? 'Unlock Academy' : authView === 'signup' ? 'Create Profile' : 'Authorize Admin'}
              </button>
            </form>

            <div className="mt-8 pt-8 border-t border-slate-100 flex flex-col gap-4 text-center">
              {authView === 'login' && (
                <>
                  <button onClick={() => setAuthView('signup')} className="text-xs font-black text-slate-500 hover:text-blue-600 uppercase tracking-widest">New here? Sign Up</button>
                  <button onClick={() => setAuthView('admin_login')} className="text-[10px] font-black text-slate-300 hover:text-slate-800 uppercase tracking-[0.2em]">Admin Gateway</button>
                </>
              )}
              {(authView === 'signup' || authView === 'admin_login') && (
                <button onClick={() => setAuthView('login')} className="text-xs font-black text-slate-500 hover:text-blue-600 uppercase tracking-widest">Back to Login</button>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  // --- Main Tutoring App Logic ---

  // Level Selection
  if (!selectedLevel) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        {currentUser.isAdmin && (
          <button onClick={() => setIsAdminPanelOpen(true)} className="absolute top-8 left-8 bg-slate-900 text-white px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:scale-105 transition-transform z-20">Admin Panel</button>
        )}
        <div className="absolute top-0 right-0 -translate-y-1/2 translate-x-1/2 w-96 h-96 bg-blue-100 rounded-full blur-3xl opacity-50"></div>
        <div className="absolute bottom-0 left-0 translate-y-1/2 -translate-x-1/2 w-96 h-96 bg-pink-100 rounded-full blur-3xl opacity-50"></div>

        <div className="max-w-4xl w-full text-center relative z-10">
          <header className="mb-14">
            <div className="flex justify-center mb-6">
              <button onClick={logout} className="bg-white px-6 py-2 rounded-full shadow-sm text-[10px] font-black text-slate-400 hover:text-red-500 transition-colors uppercase tracking-widest border border-slate-100">Sign Out</button>
            </div>
            <h1 className="text-5xl md:text-7xl font-black mb-6 tracking-tight leading-none bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 bg-clip-text text-transparent">
              Namibia NSSCO/NSSCAS <br/> Pocket Tutor
            </h1>
            <p className="text-xl md:text-2xl font-bold bg-gradient-to-r from-emerald-500 to-teal-700 bg-clip-text text-transparent max-w-2xl mx-auto">
              Welcome, {currentUser.name}. <br/>
              <span className="text-slate-800">Ready to join the Top 1%?</span>
            </p>
          </header>

          <div className="flex flex-col sm:flex-row gap-8 justify-center items-stretch">
            <button
              onClick={() => setSelectedLevel('NSSCAS')}
              className="group bg-white p-12 rounded-[2.5rem] shadow-xl hover:shadow-2xl border border-slate-100 transition-all w-full sm:w-80 flex flex-col items-center"
            >
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-8 group-hover:scale-110 transition-transform">AS</div>
              <h3 className="text-3xl font-black text-slate-800 mb-2">NSSCAS</h3>
              <p className="text-slate-500 font-medium text-sm leading-relaxed">Advanced Subsidiary (Grade 12)</p>
            </button>
            <button
              onClick={() => setSelectedLevel('NSSCO')}
              className="group bg-white p-12 rounded-[2.5rem] shadow-xl hover:shadow-2xl border border-slate-100 transition-all w-full sm:w-80 flex flex-col items-center"
            >
              <div className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-8 group-hover:scale-110 transition-transform">O</div>
              <h3 className="text-3xl font-black text-slate-800 mb-2">NSSCO</h3>
              <p className="text-slate-500 font-medium text-sm leading-relaxed">Ordinary Level (Grade 10-11)</p>
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Subject Selection
  if (!selectedSubject) {
    return (
      <div className="min-h-screen p-6 bg-slate-50">
        <div className="max-w-6xl mx-auto py-12">
          <div className="flex items-center justify-between mb-8">
            <button onClick={() => setSelectedLevel(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 font-bold transition-colors group">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 transform group-hover:-translate-x-1 transition-transform" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
              Level Select
            </button>
            <button onClick={logout} className="text-[10px] font-black text-slate-400 hover:text-red-500 transition-colors uppercase tracking-widest">Sign Out</button>
          </div>
          <header className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
              <h2 className="text-4xl font-black text-slate-900 mb-2">{selectedLevel} Subjects</h2>
              <p className="text-slate-600 text-lg">Choose your subject to join the Top 1%.</p>
            </div>
            <div className="relative w-full md:w-80">
              <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search subjects..." className="w-full bg-white border border-slate-200 rounded-2xl pl-12 pr-4 py-4 focus:ring-4 focus:ring-blue-100 outline-none font-bold text-slate-700 shadow-sm" />
              <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></div>
            </div>
          </header>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {filteredSubjects.map((s, idx) => (
              <button key={`${s.id}-${idx}`} onClick={() => handleSelectSubject(s)} className="group bg-white p-6 rounded-3xl shadow-md hover:shadow-2xl border border-slate-100 transition-all text-left flex flex-col relative overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300" style={{ animationDelay: `${idx * 50}ms` }}>
                <div className={`${s.color} text-white w-12 h-12 rounded-2xl flex items-center justify-center text-2xl mb-4 group-hover:scale-110 transition-transform shadow-lg`}>{s.icon}</div>
                <h3 className="text-xl font-black text-slate-800 mb-1">{s.id}</h3>
                <p className="text-slate-500 font-medium text-xs flex-grow leading-relaxed">{s.description}</p>
                <div className="mt-4 text-[10px] font-black text-blue-600 uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">Launch Tutoring &rarr;</div>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // Active Tutoring View
  return (
    <div className="flex flex-col h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shadow-sm sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <button onClick={resetChat} className="text-slate-400 hover:text-slate-600 p-2 rounded-full hover:bg-slate-100 transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg></button>
          <div><h2 className="text-lg font-black text-slate-800 leading-tight">{selectedLevel} <span className="text-blue-600">{selectedSubject.id}</span></h2><p className="text-xs text-slate-500 flex items-center gap-1"><span className={`w-2 h-2 ${isVoiceActive ? 'bg-red-500 animate-pulse' : 'bg-green-500'} rounded-full`}></span>{isVoiceActive ? 'Voice Interaction Live' : 'Pocket Tutor Online'}</p></div>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex flex-col items-end text-right max-w-[280px]">
            <span className="text-[10px] font-black uppercase tracking-tighter bg-gradient-to-r from-blue-600 via-purple-600 via-pink-500 via-orange-500 via-green-600 to-blue-600 bg-clip-text text-transparent leading-tight text-center">
              use your device audio recorder to record and listen when offline
            </span>
          </div>
          {messages.length > 0 && (
            <button onClick={exportSession} className="bg-white border-2 border-slate-100 hover:border-blue-200 text-slate-700 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 transition-all hover:shadow-md active:scale-95 group">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-blue-600 group-hover:animate-bounce" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              Export Log
            </button>
          )}
        </div>
      </header>

      <main ref={scrollRef} className="flex-grow overflow-y-auto px-4 py-8 max-w-3xl mx-auto w-full custom-scrollbar">
        <div className="space-y-8">
          {statusMessage && <div className="bg-blue-50 text-blue-700 px-4 py-3 rounded-2xl text-xs font-bold text-center border border-blue-100 animate-pulse">{statusMessage}</div>}
          {messages.length === 0 && !isVoiceActive && (
             <div className="text-center py-20">
                <div className="bg-blue-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-3xl shadow-inner">🎓</div>
                <h3 className="text-xl font-black text-slate-800 mb-2">Mastering {selectedSubject.id}</h3>
                <p className="text-slate-500 text-sm max-w-sm mx-auto">Start our Socratic dialogue below or tap the mic for a voice session.</p>
             </div>
          )}
          {messages.map((msg) => (
            <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} group animate-in fade-in slide-in-from-bottom-2`}>
              <div className={`max-w-[90%] rounded-[2rem] px-6 py-5 shadow-md relative ${msg.role === 'user' ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white rounded-tr-none' : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'}`}>
                <div className="prose prose-sm max-w-none font-medium leading-relaxed">{msg.content.split('\n').map((line, i) => (<p key={i} className={i > 0 ? 'mt-3' : ''}>{line}</p>))}</div>
                <div className="flex items-center justify-between mt-3"><div className="text-[9px] font-bold opacity-60">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div></div>
              </div>
            </div>
          ))}
          {isTyping && <div className="flex justify-start"><div className="bg-white border border-slate-100 rounded-[2rem] rounded-tl-none px-6 py-5 shadow-md"><div className="flex gap-2"><span className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></span><span className="w-2 h-2 bg-purple-500 rounded-full animate-bounce [animation-delay:0.2s]"></span><span className="w-2 h-2 bg-pink-500 rounded-full animate-bounce [animation-delay:0.4s]"></span></div></div></div>}
          {isVoiceActive && !statusMessage && (
            <div className="text-center py-6 animate-in fade-in zoom-in">
              <div className="inline-flex flex-col items-center">
                 <div className="relative mb-4"><div className="absolute inset-0 bg-blue-400 rounded-full animate-ping opacity-20"></div><div className="bg-blue-600 p-6 rounded-full text-white shadow-xl shadow-blue-200 relative"><svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></div></div>
                 <h4 className="font-black text-slate-800 text-xs uppercase tracking-widest">Guided Audio Active</h4>
                 <p className="text-slate-400 text-[9px] font-bold mt-1">Guided reasoning via audio stream.</p>
              </div>
            </div>
          )}
        </div>
      </main>

      <footer className="bg-white border-t border-slate-200 p-6 sticky bottom-0 z-10">
        <div className="max-w-3xl mx-auto">
          <div className="flex gap-4 items-center">
