// --- Audio Utilities ---
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const App: React.FC = () => {
  // --- Global User & Auth State ---
  const [allUsers, setAllUsers] = useState<AppUser[]>(() => {
    const saved = localStorage.getItem('pocket_tutor_users');
    return saved ? JSON.parse(saved) : [];
  });
  const [currentUser, setCurrentUser] = useState<AppUser | null>(() => {
    const saved = localStorage.getItem('pocket_tutor_session');
    return saved ? JSON.parse(saved) : null;
  });

  // --- Auth UI State ---
  const [authView, setAuthView] = useState<'login' | 'signup' | 'admin_login'>('login');
  const [authError, setAuthError] = useState<string | null>(null);
  const [authSuccess, setAuthSuccess] = useState<string | null>(null);
  const [isAdminPanelOpen, setIsAdminPanelOpen] = useState(false);

  // Form Fields
  const [nameField, setNameField] = useState('');
  const [phoneField, setPhoneField] = useState('');
  const [emailField, setEmailField] = useState('');
  const [passwordField, setPasswordField] = useState('');

  // --- Tutoring State ---
  const [selectedLevel, setSelectedLevel] = useState<Level | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<SubjectOption | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isVoiceActive, setIsVoiceActive] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  const chatRef = useRef<Chat | null>(null);
  const liveSessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('pocket_tutor_users', JSON.stringify(allUsers));
  }, [allUsers]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('pocket_tutor_session', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('pocket_tutor_session');
    }
  }, [currentUser]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isVoiceActive]);

  // --- Auth Handlers ---
  const handleSignUp = (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);
    if (allUsers.find(u => u.phone === phoneField)) {
      setAuthError("This phone number is already registered.");
      return;
    }
    const newUser: AppUser = {
      id: Date.now().toString(),
      name: nameField,
      phone: phoneField,
      password: passwordField,
      status: 'pending'
    };
    setAllUsers([...allUsers, newUser]);
    setAuthSuccess("Enrollment received! Your status is currently 'Pending Admin Review'.");
    setAuthView('login');
    setNameField('');
    setPhoneField('');
    setPasswordField('');
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);
    setAuthSuccess(null);
    const user = allUsers.find(u => u.phone === phoneField && u.password === passwordField);
    if (!user) {
      setAuthError("Invalid credentials. Verify your phone and mastery key.");
      return;
    }
    if (user.status === 'pending') {
      setAuthError("Enrollment Pending: Our administrators are still reviewing your profile.");
      return;
    }
    if (user.status === 'revoked') {
      setAuthError("Access Revoked: Please contact our support team for reactivation.");
      return;
    }
    setCurrentUser(user);
    setPhoneField('');
    setPasswordField('');
  };

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);
    if (emailField === ADMIN_EMAIL && passwordField === ADMIN_PASSWORD) {
      const admin: AppUser = {
        id: 'admin-master',
        name: 'Academy Administrator',
        phone: 'INTERNAL',
        email: ADMIN_EMAIL,
        password: ADMIN_PASSWORD,
        status: 'approved',
        isAdmin: true
      };
      setCurrentUser(admin);
      setIsAdminPanelOpen(true);
      setEmailField('');
      setPasswordField('');
    } else {
      setAuthError("Critical Error: Administrative credentials mismatch.");
    }
  };

  const logout = () => {
    setCurrentUser(null);
    setIsAdminPanelOpen(false);
    resetChat();
  };

  const setStatus = (id: string, status: UserStatus) => {
    setAllUsers(prev => prev.map(u => u.id === id ? { ...u, status } : u));
  };

  // --- Tutoring Logic ---
  const stopVoiceMode = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.then((s: any) => { try { s.close(); } catch(e) {} });
      liveSessionRef.current = null;
    }
    if (inputAudioContextRef.current) {
      inputAudioContextRef.current.close().catch(() => {});
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close().catch(() => {});
      outputAudioContextRef.current = null;
    }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    setIsVoiceActive(false);
    setStatusMessage(null);
  };

  const startVoiceMode = async () => {
    if (!selectedSubject) return;
    setStatusMessage("Activating Neuro-Audio Link...");
    setIsVoiceActive(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      await inputCtx.resume();
      await outputCtx.resume();
      inputAudioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const sessionPromise = connectTutorLive(selectedSubject.id, selectedSubject.level, {
        onopen: () => { 
          setStatusMessage(null);
          const source = inputCtx.createMediaStreamSource(stream);
          const processor = inputCtx.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const data = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(data.length);
            for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({
              media: {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000'
              }
            }));
          };
          source.connect(processor);
          processor.connect(inputCtx.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (base64Audio && outputAudioContextRef.current) {
            const ctx = outputAudioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }
          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }
        },
        onerror: (e) => { console.error(e); stopVoiceMode(); },
        onclose: () => stopVoiceMode()
      });
      liveSessionRef.current = sessionPromise;
    } catch (err) {
      setIsVoiceActive(false);
      setStatusMessage("Audio peripherals required for this feature.");
    }
  };

  const handleSelectSubject = useCallback((option: SubjectOption) => {
    setSelectedSubject(option);
    const tutorChat = createChatInstance(option.id, option.level);
    chatRef.current = tutorChat;
    const greeting = `Salutations, Scholar ${currentUser?.name}! I am your ${option.level} ${option.id} specialist. What complex problem shall we unravel through logic today?`;
    setMessages([{ id: Date.now().toString(), role: 'assistant', content: greeting, timestamp: new Date() }]);
  }, [currentUser]);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;
    const userMessage: Message = { id: Date.now().toString(), role: 'user', content: inputValue, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsTyping(true);
    try {
      const response: GenerateContentResponse = await chatRef.current.sendMessage({ message: inputValue });
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "Your reasoning is noted. Can we expand on the previous premise?",
        timestamp: new Date(),
        groundingChunks: response.candidates?.[0]?.groundingMetadata?.groundingChunks
      };
      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'assistant', content: "Our processing link experienced a surge. Please repeat your last inquiry.", timestamp: new Date() }]);
    } finally { setIsTyping(false); }
  };

  const resetChat = () => {
    stopVoiceMode();
    setSelectedSubject(null);
    setMessages([]);
    chatRef.current = null;
  };

  const exportSession = () => {
    if (!selectedSubject || messages.length === 0) return;
    let content = `MASTER ACADEMY SESSION LOG\nLevel: ${selectedLevel}\nSubject: ${selectedSubject.id}\nStudent: ${currentUser?.name}\nDate: ${new Date().toLocaleString()}\n\n`;
    messages.forEach(msg => { content += `[${msg.role === 'user' ? 'STUDENT' : 'TUTOR'}]: ${msg.content}\n\n`; });
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Academy_Session_${selectedSubject.id}_${Date.now()}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const filteredSubjects = SUBJECTS.filter(s => s.level === selectedLevel && (searchQuery === '' || s.id.toLowerCase().includes(searchQuery.toLowerCase())));

  // --- Background Elements ---
  const BackgroundBlobs = () => (
    <>
      <div className="absolute top-[-10%] left-[-10%] w-[500px] h-[500px] bg-blue-400/30 rounded-full blur-[120px] animate-pulse"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[500px] h-[500px] bg-pink-400/30 rounded-full blur-[120px] animate-pulse delay-700"></div>
      <div className="absolute top-[20%] right-[10%] w-[300px] h-[300px] bg-purple-400/20 rounded-full blur-[100px] animate-bounce duration-[10s]"></div>
      <div className="absolute bottom-[20%] left-[10%] w-[300px] h-[300px] bg-emerald-400/20 rounded-full blur-[100px] animate-bounce duration-[12s]"></div>
    </>
  );

  // --- VIEWS ---

  // 1. Admin Panel
  if (currentUser?.isAdmin && isAdminPanelOpen) {
    return (
      <div className="min-h-screen bg-slate-950 text-white p-8 overflow-y-auto relative">
        <BackgroundBlobs />
        <div className="max-w-6xl mx-auto relative z-10">
          <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-12">
            <div>
              <h1 className="text-5xl font-black tracking-tighter bg-gradient-to-r from-emerald-400 via-teal-400 to-cyan-400 bg-clip-text text-transparent">Nexus Command</h1>
              <p className="text-slate-500 font-bold uppercase tracking-[0.3em] text-[10px] mt-2">Administrative Master Node</p>
            </div>
            <div className="flex gap-4">
              <button onClick={() => setIsAdminPanelOpen(false)} className="glass px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-white/10 transition-all border border-white/5">Back to Academy</button>
              <button onClick={logout} className="bg-red-500/10 text-red-500 border border-red-500/20 px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all shadow-xl shadow-red-500/10">Terminate Session</button>
            </div>
          </header>

          <div className="glass rounded-[3rem] border border-white/10 shadow-2xl overflow-hidden mb-10">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="bg-white/5 text-slate-500 text-[9px] font-black uppercase tracking-[0.25em] border-b border-white/5">
                    <th className="px-10 py-8">Enrollment Data</th>
                    <th className="px-10 py-8">Contact Node</th>
                    <th className="px-10 py-8">Access Level</th>
                    <th className="px-10 py-8 text-right">Master Override</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {allUsers.length === 0 ? (
                    <tr><td colSpan={4} className="px-10 py-24 text-center text-slate-600 font-bold italic tracking-widest uppercase text-xs">No pending student protocols found in the database.</td></tr>
                  ) : (
                    allUsers.map(user => (
                      <tr key={user.id} className="group hover:bg-white/5 transition-colors">
                        <td className="px-10 py-8">
                          <div className="font-black text-lg text-slate-100">{user.name}</div>
                          <div className="text-[10px] text-emerald-500/60 font-mono mt-1">UID: {user.id}</div>
                        </td>
                        <td className="px-10 py-8 font-bold text-slate-400 tracking-tight">{user.phone}</td>
                        <td className="px-10 py-8">
                          <span className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-[0.15em] border ${
                            user.status === 'approved' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30' :
                            user.status === 'revoked' ? 'bg-red-500/10 text-red-400 border-red-500/30' :
                            'bg-amber-500/10 text-amber-400 border-amber-500/30'
                          }`}>
                            {user.status}
                          </span>
                        </td>
                        <td className="px-10 py-8 text-right">
                          <div className="flex justify-end gap-3">
                            {user.status !== 'approved' && (
                              <button onClick={() => setStatus(user.id, 'approved')} className="bg-emerald-500 text-white px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-emerald-500/20 hover:scale-110 active:scale-95 transition-all">Grant Access</button>
                            )}
                            {user.status !== 'revoked' && (
                              <button onClick={() => setStatus(user.id, 'revoked')} className="bg-red-500/10 text-red-500 border border-red-500/20 px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-red-500 hover:text-white hover:scale-110 active:scale-95 transition-all">Revoke</button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // 2. Auth Interface
  if (!currentUser) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        <BackgroundBlobs />
        <div className="max-w-md w-full relative z-10">
          <div className="text-center mb-12">
            <h1 className="text-5xl md:text-6xl font-black mb-4 tracking-tighter leading-none bg-gradient-to-br from-slate-900 via-blue-800 to-indigo-900 bg-clip-text text-transparent">
              {authView === 'login' ? 'Mastery Entry' : authView === 'signup' ? 'Enrollment' : 'Nexus Portal'}
            </h1>
            <p className="text-slate-400 font-black text-[11px] uppercase tracking-[0.3em] leading-relaxed">
              {authView === 'admin_login' ? 'Authorized Logic Node' : 'Join the Elite 1% Achievers'}
            </p>
          </div>

          <div className="glass p-10 rounded-[3rem] shadow-2xl border border-white shadow-blue-900/10">
            {authSuccess && <div className="bg-emerald-50 text-emerald-600 p-5 rounded-3xl text-[12px] font-black mb-8 border border-emerald-100 text-center animate-in fade-in slide-in-from-top-4 uppercase tracking-widest">{authSuccess}</div>}
            {authError && <div className="bg-red-50 text-red-500 p-5 rounded-3xl text-[12px] font-black mb-8 border border-red-100 text-center animate-shake uppercase tracking-widest">{authError}</div>}

            <form onSubmit={authView === 'login' ? handleLogin : authView === 'signup' ? handleSignUp : handleAdminLogin} className="space-y-8">
              {authView === 'signup' && (
                <div className="space-y-3">
                  <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] ml-6">Scholar Name</label>
                  <input type="text" value={nameField} onChange={(e) => setNameField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-[2rem] px-8 py-5 focus:ring-4 focus:ring-blue-100 outline-none transition-all font-black text-slate-800 shadow-sm" placeholder="e.g. Johannes H." />
                </div>
              )}

              {authView === 'admin_login' ? (
                <div className="space-y-3">
                  <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] ml-6">Admin Identity</label>
                  <input type="email" value={emailField} onChange={(e) => setEmailField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-[2rem] px-8 py-5 focus:ring-4 focus:ring-blue-100 outline-none transition-all font-black text-slate-800 shadow-sm" placeholder="admin@academy.na" />
                </div>
              ) : (
                <div className="space-y-3">
                  <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] ml-6">Contact Number</label>
                  <input type="tel" value={phoneField} onChange={(e) => setPhoneField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-[2rem] px-8 py-5 focus:ring-4 focus:ring-blue-100 outline-none transition-all font-black text-slate-800 shadow-sm" placeholder="+264 ..." />
                </div>
              )}

              <div className="space-y-3">
                <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] ml-6">Mastery Key</label>
                <input type="password" value={passwordField} onChange={(e) => setPasswordField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-[2rem] px-8 py-5 focus:ring-4 focus:ring-blue-100 outline-none transition-all font-black text-slate-800 shadow-sm" placeholder="••••••••" />
              </div>

              <button type="submit" className="w-full bg-gradient-to-br from-slate-900 via-indigo-950 to-slate-900 text-white font-black py-6 rounded-[2rem] shadow-2xl shadow-blue-900/20 hover:scale-[1.03] active:scale-[0.97] transition-all uppercase tracking-[0.25em] text-[12px] mt-6">
                {authView === 'login' ? 'Activate Entry' : authView === 'signup' ? 'Initiate Profile' : 'Authorize Node'}
              </button>
            </form>

            <div className="mt-10 pt-10 border-t border-slate-100 flex flex-col gap-5 text-center">
              {authView === 'login' && (
                <>
                  <button onClick={() => { setAuthView('signup'); setAuthError(null); setAuthSuccess(null); }} className="text-xs font-black text-slate-400 hover:text-blue-600 uppercase tracking-widest transition-colors">New Scholar? Apply Now</button>
                  <button onClick={() => { setAuthView('admin_login'); setAuthError(null); setAuthSuccess(null); }} className="text-[10px] font-black text-slate-300 hover:text-slate-800 uppercase tracking-[0.3em] transition-colors">Admin Gateway</button>
                </>
              )}
              {(authView === 'signup' || authView === 'admin_login') && (
                <button onClick={() => { setAuthView('login'); setAuthError(null); setAuthSuccess(null); }} className="text-xs font-black text-slate-400 hover:text-blue-600 uppercase tracking-widest transition-colors">Return to Entry Point</button>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  // 3. Level Selection
  if (!selectedLevel) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        <BackgroundBlobs />
        {currentUser.isAdmin && (
          <button onClick={() => setIsAdminPanelOpen(true)} className="absolute top-8 left-8 bg-slate-950 text-white px-8 py-4 rounded-3xl text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl hover:scale-110 transition-all z-20 border border-white/10 hover:bg-emerald-600">Admin Dashboard</button>
        )}
        <div className="max-w-5xl w-full text-center relative z-10">
          <header className="mb-20 animate-in fade-in slide-in-from-top-10 duration-1000">
            <div className="flex justify-center mb-8">
              <button onClick={logout} className="glass px-10 py-3 rounded-full shadow-lg text-[11px] font-black text-slate-400 hover:text-red-500 transition-all uppercase tracking-[0.2em] border border-white">Sign Out Protocol</button>
            </div>
            <h1 className="text-6xl md:text-8xl font-black mb-8 tracking-tighter leading-none bg-gradient-to-br from-slate-900 via-indigo-800 to-slate-950 bg-clip-text text-transparent">
              Namibia Academy <br/> Pocket Tutor
            </h1>
            <p className="text-2xl md:text-3xl font-bold bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent max-w-3xl mx-auto leading-relaxed">
              Welcome back, {currentUser.name}. <br/>
              <span className="text-slate-900">Define your current mastery objective.</span>
            </p>
          </header>

          <div className="flex flex-col sm:flex-row gap-10 justify-center items-stretch">
            <button
              onClick={() => setSelectedLevel('NSSCAS')}
              className="group bg-white p-14 rounded-[4rem] shadow-2xl hover:shadow-[0_40px_80px_rgba(37,99,235,0.15)] border border-slate-100 transition-all w-full sm:w-96 flex flex-col items-center hover:scale-105 active:scale-95"
            >
              <div className="bg-gradient-to-br from-blue-600 via-blue-700 to-indigo-800 text-white w-24 h-24 rounded-[2rem] flex items-center justify-center text-5xl mb-10 group-hover:scale-125 transition-transform shadow-2xl shadow-blue-300">AS</div>
              <h3 className="text-4xl font-black text-slate-900 mb-3">NSSCAS</h3>
              <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">Advanced Subsidiary (Grade 12)</p>
            </button>
            <button
              onClick={() => setSelectedLevel('NSSCO')}
              className="group bg-white p-14 rounded-[4rem] shadow-2xl hover:shadow-[0_40px_80px_rgba(16,185,129,0.15)] border border-slate-100 transition-all w-full sm:w-96 flex flex-col items-center hover:scale-105 active:scale-95"
            >
              <div className="bg-gradient-to-br from-emerald-500 via-emerald-600 to-teal-700 text-white w-24 h-24 rounded-[2rem] flex items-center justify-center text-5xl mb-10 group-hover:scale-125 transition-transform shadow-2xl shadow-emerald-300">O</div>
              <h3 className="text-4xl font-black text-slate-900 mb-3">NSSCO</h3>
              <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">Ordinary Level (Grade 10-11)</p>
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 4. Subject Selection
  if (!selectedSubject) {
    return (
      <div className="min-h-screen p-8 md:p-12 bg-slate-50 relative overflow-hidden">
        <BackgroundBlobs />
        <div className="max-w-7xl mx-auto py-12 relative z-10">
          <div className="flex items-center justify-between mb-12">
            <button onClick={() => setSelectedLevel(null)} className="flex items-center gap-3 text-slate-500 hover:text-slate-900 font-black transition-all group text-sm uppercase tracking-widest">
              <div className="p-3 bg-white rounded-2xl shadow-md group-hover:-translate-x-2 transition-transform border border-slate-100"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg></div>
              Mastery Levels
            </button>
            <button onClick={logout} className="text-[11px] font-black text-slate-400 hover:text-red-500 transition-colors uppercase tracking-[0.2em]">Terminate Node</button>
          </div>

          <header className="mb-16 flex flex-col md:flex-row md:items-end justify-between gap-10">
            <div>
              <h2 className="text-6xl font-black text-slate-900 mb-3 tracking-tighter">{selectedLevel} <span className="bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">Specializations</span></h2>
              <p className="text-slate-400 font-bold text-lg uppercase tracking-widest">Select a subject to initiate Socratic Guided Reasoning.</p>
            </div>
            <div className="relative w-full md:w-96 group">
              <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search specialized subjects..." className="w-full bg-white border border-slate-200 rounded-3xl pl-16 pr-6 py-6 focus:ring-[12px] focus:ring-blue-100 outline-none font-black text-slate-700 shadow-xl transition-all" />
              <div className="absolute left-6 top-1/2 -translate-y-1/2 text-blue-500 group-hover:scale-125 transition-transform"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></div>
            </div>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
            {filteredSubjects.map((s, idx) => (
              <button 
                key={`${s.id}-${idx}`} 
                onClick={() => handleSelectSubject(s)} 
                className="group bg-white p-10 rounded-[3rem] shadow-xl hover:shadow-[0_40px_80px_rgba(0,0,0,0.08)] border border-slate-100 transition-all text-left flex flex-col relative overflow-hidden animate-in fade-in slide-in-from-bottom-6 duration-500 hover:-translate-y-2" 
                style={{ animationDelay: `${idx * 60}ms` }}
              >
                <div className="absolute top-0 right-0 p-8 opacity-0 group-hover:opacity-10 transition-opacity">
                  <div className={`w-32 h-32 ${s.color} rounded-full blur-[40px]`}></div>
                </div>
                <div className={`${s.color} text-white w-16 h-16 rounded-[1.5rem] flex items-center justify-center text-3xl mb-8 group-hover:scale-125 transition-all shadow-2xl group-hover:rotate-6`}>{s.icon}</div>
                <h3 className="text-2xl font-black text-slate-900 mb-3 group-hover:text-blue-600 transition-colors">{s.id}</h3>
                <p className="text-slate-400 font-bold text-xs flex-grow leading-relaxed uppercase tracking-wider">{s.description}</p>
                <div className="mt-8 flex items-center gap-2 text-[11px] font-black text-blue-600 uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-all translate-y-4 group-hover:translate-y-0">
                  Launch Tutoring 
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                </div>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // 5. Tutoring Active View
  return (
    <div className="flex flex-col h-screen bg-slate-50 relative overflow-hidden">
      <BackgroundBlobs />
      <header className="glass border-b border-white/50 px-8 py-6 flex items-center justify-between shadow-xl sticky top-0 z-20 backdrop-blur-2xl">
        <div className="flex items-center gap-6">
          <button onClick={resetChat} className="bg-white p-3 rounded-2xl shadow-lg border border-slate-100 text-slate-400 hover:text-blue-600 transition-all hover:scale-110 active:scale-90 group">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 group-hover:-translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          </button>
          <div>
            <h2 className="text-2xl font-black text-slate-900 leading-none flex items-center gap-2">
              {selectedLevel} <span className="text-blue-600">{selectedSubject.id}</span>
            </h2>
            <p className="text-[10px] font-black text-slate-400 mt-2 uppercase tracking-[0.2em] flex items-center gap-2">
              <span className={`w-2.5 h-2.5 ${isVoiceActive ? 'bg-red-500 animate-ping' : 'bg-emerald-500'} rounded-full shadow-lg`}></span>
              {isVoiceActive ? 'Neural Voice Live' : 'Socratic Matrix Active'}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-8">
          <div className="hidden lg:flex flex-col items-end text-right">
            <span className="text-[10px] font-black uppercase tracking-[0.2em] bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent">Top 1% Achieve Tip</span>
            <span className="text-xs font-bold text-slate-600">Record locally for offline study cycles.</span>
          </div>
          {messages.length > 0 && (
            <button onClick={exportSession} className="bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-[0.15em] flex items-center gap-3 transition-all hover:scale-105 active:scale-95 shadow-xl shadow-slate-900/20 group">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-emerald-400 group-hover:animate-bounce" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              Dump session
            </button>
          )}
        </div>
      </header>

      <main ref={scrollRef} className="flex-grow overflow-y-auto px-6 py-12 max-w-4xl mx-auto w-full custom-scrollbar relative z-10">
        <div className="space-y-12 pb-20">
          {statusMessage && <div className="glass bg-blue-600 text-white px-8 py-5 rounded-[2rem] text-[11px] font-black uppercase tracking-[0.2em] text-center border-none shadow-2xl animate-pulse mx-auto max-w-sm">{statusMessage}</div>}

          {messages.length === 0 && !isVoiceActive && (
             <div className="text-center py-24 animate-in fade-in slide-in-from-bottom-10 duration-700">
                <div className={`w-32 h-32 ${selectedSubject.color} rounded-[3rem] flex items-center justify-center mx-auto mb-10 text-5xl shadow-2xl shadow-blue-200 rotate-6 animate-bounce duration-[3s]`}>{selectedSubject.icon}</div>
                <h3 className="text-4xl font-black text-slate-900 mb-4 tracking-tighter">Initiate Guided Reasoning</h3>
                <p className="text-slate-400 font-bold text-base max-w-md mx-auto leading-relaxed">Prepare for a Socratic dialogue. I will prompt you with logic rather than provide direct answers.</p>
             </div>
          )}

          {messages.map((msg) => (
            <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} group animate-in fade-in slide-in-from-bottom-4`}>
              <div className={`max-w-[88%] rounded-[3rem] px-8 py-7 shadow-2xl relative border border-white/50 ${msg.role === 'user' ? 'bg-gradient-to-br from-blue-600 via-blue-700 to-indigo-800 text-white rounded-tr-none' : 'bg-white/90 backdrop-blur-xl text-slate-800 rounded-tl-none'}`}>
                <div className="prose prose-sm max-w-none font-bold text-base leading-relaxed">
                  {msg.content.split('\n').map((line, i) => (<p key={i} className={i > 0 ? 'mt-4' : ''}>{line}</p>))}
                </div>
                <div className={`flex items-center justify-between mt-5 text-[10px] font-black uppercase tracking-widest ${msg.role === 'user' ? 'opacity-60' : 'text-blue-500'}`}>
                  <span>{msg.role === 'user' ? currentUser?.name : `AI ${selectedSubject.id} SPECIALIST`}</span>
                  <span>{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                </div>
              </div>
            </div>
          ))}

          {isTyping && (
            <div className="flex justify-start">
              <div className="bg-white/50 backdrop-blur-md rounded-[2.5rem] rounded-tl-none px-8 py-6 shadow-xl border border-white">
                <div className="flex gap-2">
