    setNameField('');
    setPhoneField('');
    setPasswordField('');
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);
    setAuthSuccess(null);
    const user = allUsers.find(u => u.phone === phoneField && u.password === passwordField);
    if (!user) {
      setAuthError("Invalid credentials. Verify your phone and mastery key.");
      return;
    }
    if (user.status === 'pending') {
      setAuthError("Enrollment Pending: Our administrators are still reviewing your profile.");
      return;
    }
