    messages.forEach(msg => { content += `[${msg.role === 'user' ? 'STUDENT' : 'TUTOR'}]: ${msg.content}\n\n`; });
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Academy_Session_${selectedSubject.id}_${Date.now()}.txt`;
    link.click();
