      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isVoiceActive]);

  // --- Auth Handlers ---
  const handleSignUp = (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);
    if (allUsers.find(u => u.phone === phoneField)) {
      setAuthError("This phone number is already registered.");
      return;
    }
    const newUser: AppUser = {
      id: Date.now().toString(),
      name: nameField,
      phone: phoneField,
      password: passwordField,
      status: 'pending'
    };
    setAllUsers([...allUsers, newUser]);
    setAuthSuccess("Enrollment received! Please follow payment instructions below for account approval.");
    setAuthView('login');
    setNameField('');
    setPhoneField('');
    setPasswordField('');
    setShowPassword(false);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);
    setAuthSuccess(null);
    const user = allUsers.find(u => u.phone === phoneField && u.password === passwordField);
    if (!user) {
      setAuthError("Invalid credentials. Verify your phone and mastery key.");
      return;
    }
    if (user.status === 'pending') {
      setAuthError("Enrollment Pending: Call 0813879841 for payment and approval.");
      return;
    }
    if (user.status === 'revoked') {
      setAuthError("Access Revoked: Contact 0813879841 for reactivation.");
      return;
    }
    setCurrentUser(user);
    setPhoneField('');
    setPasswordField('');
    setShowPassword(false);
  };

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);
    if (emailField === ADMIN_EMAIL && passwordField === ADMIN_PASSWORD) {
      const admin: AppUser = {
        id: 'admin-master',
        name: 'Academy Administrator',
        phone: 'INTERNAL',
        email: ADMIN_EMAIL,
        password: ADMIN_PASSWORD,
        status: 'approved',
        isAdmin: true
      };
      setCurrentUser(admin);
      setIsAdminPanelOpen(true);
      setEmailField('');
      setPasswordField('');
      setShowPassword(false);
    } else {
      setAuthError("Critical Error: Administrative credentials mismatch.");
    }
  };

  const logout = () => {
    setCurrentUser(null);
    setIsAdminPanelOpen(false);
    resetChat();
  };

  const setStatus = (id: string, status: UserStatus) => {
    setAllUsers(prev => prev.map(u => u.id === id ? { ...u, status } : u));
  };

  // --- Tutoring Logic ---
  const stopVoiceMode = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.then((s: any) => { try { s.close(); } catch(e) {} });
      liveSessionRef.current = null;
    }
    if (inputAudioContextRef.current) {
      inputAudioContextRef.current.close().catch(() => {});
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close().catch(() => {});
      outputAudioContextRef.current = null;
    }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    setIsVoiceActive(false);
    setStatusMessage(null);
  };

  const startVoiceMode = async () => {
    if (!selectedSubject) return;
    setStatusMessage("Activating Neuro-Audio Link...");
    setIsVoiceActive(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      await inputCtx.resume();
      await outputCtx.resume();
      inputAudioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const sessionPromise = connectTutorLive(selectedSubject.id, selectedSubject.level, {
        onopen: () => { 
          setStatusMessage(null);
          const source = inputCtx.createMediaStreamSource(stream);
          const processor = inputCtx.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const data = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(data.length);
            for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({
              media: {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000'
              }
            }));
          };
          source.connect(processor);
          processor.connect(inputCtx.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (base64Audio && outputAudioContextRef.current) {
            const ctx = outputAudioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }
          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }
        },
        onerror: (e) => { console.error(e); stopVoiceMode(); },
        onclose: () => stopVoiceMode()
      });
      liveSessionRef.current = sessionPromise;
    } catch (err) {
      setIsVoiceActive(false);
      setStatusMessage("Audio peripherals required for this feature.");
    }
  };

  const handleSelectSubject = useCallback((option: SubjectOption) => {
    setSelectedSubject(option);
    const tutorChat = createChatInstance(option.id, option.level);
    chatRef.current = tutorChat;
    const greeting = `Salutations, Scholar ${currentUser?.name}! I am your ${option.level} ${option.id} specialist. What complex problem shall we unravel through logic today?`;
    setMessages([{ id: Date.now().toString(), role: 'assistant', content: greeting, timestamp: new Date() }]);
  }, [currentUser]);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;
    const userMessage: Message = { id: Date.now().toString(), role: 'user', content: inputValue, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsTyping(true);
    try {
      const response: GenerateContentResponse = await chatRef.current.sendMessage({ message: inputValue });
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "Your reasoning is noted. Can we expand on the previous premise?",
        timestamp: new Date(),
        groundingChunks: response.candidates?.[0]?.groundingMetadata?.groundingChunks as any
      };
      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'assistant', content: "Our processing link experienced a surge. Please repeat your last inquiry.", timestamp: new Date() }]);
    } finally { setIsTyping(false); }
  };

  const resetChat = () => {
    stopVoiceMode();
    setSelectedSubject(null);
    setMessages([]);
    chatRef.current = null;
  };

  const exportSession = () => {
    if (!selectedSubject || messages.length === 0) return;
    let content = `MASTER ACADEMY SESSION LOG\nLevel: ${selectedLevel}\nSubject: ${selectedSubject.id}\nStudent: ${currentUser?.name}\nDate: ${new Date().toLocaleString()}\n\n`;
    messages.forEach(msg => { content += `[${msg.role === 'user' ? 'STUDENT' : 'TUTOR'}]: ${msg.content}\n\n`; });
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Academy_Session_${selectedSubject.id}_${Date.now()}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const filteredSubjects = SUBJECTS.filter(s => s.level === selectedLevel && (searchQuery === '' || s.id.toLowerCase().includes(searchQuery.toLowerCase())));

  // --- VIEWS ---

  // 1. Admin Panel
  if (currentUser?.isAdmin && isAdminPanelOpen) {
    return (
      <div className="min-h-screen bg-slate-950 text-white p-8 overflow-y-auto relative">
        <BackgroundBlobs />
        <div className="max-w-6xl mx-auto relative z-10">
          <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-12">
            <div>
              <h1 className="text-5xl font-black tracking-tighter bg-gradient-to-r from-emerald-400 via-teal-400 to-cyan-400 bg-clip-text text-transparent">Nexus Command</h1>
              <p className="text-slate-500 font-bold uppercase tracking-[0.3em] text-[10px] mt-2">Administrative Master Node</p>
            </div>
            <div className="flex gap-4">
              <button onClick={() => setIsAdminPanelOpen(false)} className="glass px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-white/10 transition-all border border-white/5">Back to Academy</button>
              <button onClick={logout} className="bg-red-500/10 text-red-500 border border-red-500/20 px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all shadow-xl shadow-red-500/10">Terminate Session</button>
            </div>
          </header>

          <div className="glass rounded-[3rem] border border-white/10 shadow-2xl overflow-hidden mb-10">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="bg-white/5 text-slate-500 text-[9px] font-black uppercase tracking-[0.25em] border-b border-white/5">
                    <th className="px-10 py-8">Enrollment Data</th>
                    <th className="px-10 py-8">Contact Node</th>
                    <th className="px-10 py-8">Access Level</th>
                    <th className="px-10 py-8 text-right">Master Override</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {allUsers.length === 0 ? (
                    <tr><td colSpan={4} className="px-10 py-24 text-center text-slate-600 font-bold italic tracking-widest uppercase text-xs">No pending student protocols found in the database.</td></tr>
                  ) : (
                    allUsers.map(user => (
                      <tr key={user.id} className="group hover:bg-white/5 transition-colors">
                        <td className="px-10 py-8">
                          <div className="font-black text-lg text-slate-100">{user.name}</div>
                          <div className="text-[10px] text-emerald-500/60 font-mono mt-1">UID: {user.id}</div>
                        </td>
                        <td className="px-10 py-8 font-bold text-slate-400 tracking-tight">{user.phone}</td>
                        <td className="px-10 py-8">
                          <span className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-[0.15em] border ${
                            user.status === 'approved' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30' :
                            user.status === 'revoked' ? 'bg-red-500/10 text-red-400 border-red-500/30' :
                            'bg-amber-500/10 text-amber-400 border-amber-500/30'
                          }`}>
                            {user.status}
                          </span>
                        </td>
                        <td className="px-10 py-8 text-right">
                          <div className="flex justify-end gap-3">
                            {user.status !== 'approved' && (
                              <button onClick={() => setStatus(user.id, 'approved')} className="bg-emerald-500 text-white px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-emerald-500/20 hover:scale-110 active:scale-95 transition-all">Grant Access</button>
                            )}
                            {user.status !== 'revoked' && (
                              <button onClick={() => setStatus(user.id, 'revoked')} className="bg-red-500/10 text-red-500 border border-red-500/20 px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-red-500 hover:text-white hover:scale-110 active:scale-95 transition-all">Revoke</button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // 2. Auth Interface
  if (!currentUser) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        <BackgroundBlobs />
        <div className={`w-full relative z-10 flex flex-col items-center ${authView === 'signup' ? 'max-w-4xl' : 'max-w-md'}`}>
          <div className="text-center mb-12">
            <h1 className="text-5xl md:text-6xl font-black mb-4 tracking-tighter leading-none">
               <span className="bg-gradient-to-br from-indigo-600 via-purple-600 to-rose-600 bg-clip-text text-transparent">
                  {authView === 'login' ? 'Mastery' : authView === 'signup' ? 'Enroll' : 'Nexus'}
               </span>
               {' '}
               <span className="bg-gradient-to-br from-emerald-600 via-teal-600 to-cyan-600 bg-clip-text text-transparent">
                  {authView === 'login' ? 'Entry' : authView === 'signup' ? 'ment' : 'Portal'}
               </span>
            </h1>
            <p className="text-slate-400 font-black text-[11px] uppercase tracking-[0.3em] leading-relaxed">
               {authView === 'admin_login' ? (
                  <span className="bg-gradient-to-r from-red-500 via-orange-500 to-yellow-500 bg-clip-text text-transparent">Authorized Logic Node</span>
               ) : (
                  <span className="bg-gradient-to-r from-blue-400 via-indigo-500 to-purple-600 bg-clip-text text-transparent">Join the Elite 1% Achievers</span>
               )}
            </p>
          </div>

          <div className={`glass rounded-[3rem] shadow-2xl border border-white shadow-blue-900/10 flex flex-col md:flex-row overflow-hidden w-full transition-all duration-500`}>
            {/* Main Form Section */}
            <div className={`p-10 w-full ${authView === 'signup' ? 'md:w-1/2' : 'w-full'}`}>
              {authSuccess && <div className="bg-gradient-to-r from-emerald-50 to-teal-50 text-emerald-600 p-5 rounded-3xl text-[12px] font-black mb-8 border border-emerald-100 text-center animate-in fade-in slide-in-from-top-4 uppercase tracking-widest">{authSuccess}</div>}
              {authError && <div className="bg-gradient-to-r from-rose-50 to-pink-50 text-red-500 p-5 rounded-3xl text-[12px] font-black mb-8 border border-red-100 text-center animate-shake uppercase tracking-widest">{authError}</div>}

              <form onSubmit={authView === 'login' ? handleLogin : authView === 'signup' ? handleSignUp : handleAdminLogin} className="space-y-8">
                {authView === 'signup' && (
                  <div className="space-y-3">
                    <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] ml-6">Scholar Name</label>
                    <input type="text" value={nameField} onChange={(e) => setNameField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-[2rem] px-8 py-5 focus:ring-4 focus:ring-indigo-200 outline-none transition-all font-black text-slate-800 shadow-sm" placeholder="e.g. Johannes H." />
                  </div>
                )}

                {authView === 'admin_login' ? (
                  <div className="space-y-3">
                    <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] ml-6">Admin Identity</label>
                    <input type="email" value={emailField} onChange={(e) => setEmailField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-[2rem] px-8 py-5 focus:ring-4 focus:ring-rose-200 outline-none transition-all font-black text-slate-800 shadow-sm" placeholder="admin@academy.na" />
                  </div>
                ) : (
                  <div className="space-y-3">
                    <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] ml-6">Contact Number</label>
                    <input type="tel" value={phoneField} onChange={(e) => setPhoneField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-[2rem] px-8 py-5 focus:ring-4 focus:ring-teal-200 outline-none transition-all font-black text-slate-800 shadow-sm" placeholder="+264 ..." />
                  </div>
                )}

                <PasswordInput 
                  value={passwordField} 
                  onChange={setPasswordField} 
                  placeholder="••••••••" 
                  label="Mastery Key"
                  showPassword={showPassword}
                  setShowPassword={setShowPassword}
                />

                <button type="submit" className="w-full bg-gradient-to-r from-indigo-600 via-purple-700 to-indigo-900 text-white font-black py-6 rounded-[2rem] shadow-2xl shadow-blue-900/20 hover:scale-[1.03] active:scale-[0.97] transition-all uppercase tracking-[0.25em] text-[12px] mt-6">
                  {authView === 'login' ? 'Activate Entry' : authView === 'signup' ? 'Initiate Profile' : 'Authorize Node'}
                </button>
              </form>

              <div className="mt-10 pt-10 border-t border-slate-100 flex flex-col gap-5 text-center">
                {authView === 'login' && (
                  <>
                    <button onClick={() => { setAuthView('signup'); setAuthError(null); setAuthSuccess(null); setShowPassword(false); }} className="text-xs font-black bg-gradient-to-r from-orange-400 to-rose-500 bg-clip-text text-transparent hover:scale-105 transition-all uppercase tracking-widest">New Scholar? Apply Now</button>
                    <button onClick={() => { setAuthView('admin_login'); setAuthError(null); setAuthSuccess(null); setShowPassword(false); }} className="text-[10px] font-black text-slate-300 hover:text-slate-800 uppercase tracking-[0.3em] transition-colors">Admin Gateway</button>
                  </>
                )}
                {(authView === 'signup' || authView === 'admin_login') && (
                  <button onClick={() => { setAuthView('login'); setAuthError(null); setAuthSuccess(null); setShowPassword(false); }} className="text-xs font-black bg-gradient-to-r from-blue-500 to-teal-500 bg-clip-text text-transparent hover:scale-105 transition-all uppercase tracking-widest">Return to Entry Point</button>
                )}
              </div>
            </div>

            {/* Payment Section - Only visible during Sign Up */}
            {authView === 'signup' && (
              <div className="w-full md:w-1/2 bg-slate-900 p-10 flex flex-col justify-center text-white relative">
                <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-br from-blue-500 via-purple-500 to-pink-500 opacity-20 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
                <h3 className="text-2xl font-black mb-6 tracking-tight bg-gradient-to-r from-emerald-400 via-teal-400 to-cyan-400 bg-clip-text text-transparent uppercase tracking-wider">Access Protocol</h3>
                <p className="text-slate-400 text-xs font-bold leading-relaxed mb-8 uppercase tracking-widest">
                  Unlock premium Socratic tutoring nodes by completing your enrollment payment. Access is verified within minutes.
                </p>

                <div className="space-y-4 mb-10">
                  <div className="flex items-center gap-4 bg-white/5 border border-white/10 p-4 rounded-2xl transition-all hover:bg-white/10 group cursor-default">
                    <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center font-black text-xs text-white shadow-lg shadow-emerald-500/20 group-hover:scale-110 transition-transform">FNB</div>
                    <div>
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest">FNB Namibia</div>
                      <div className="text-sm font-black text-emerald-400">eWallet</div>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 bg-white/5 border border-white/10 p-4 rounded-2xl transition-all hover:bg-white/10 group cursor-default">
                    <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center font-black text-xs text-white shadow-lg shadow-blue-500/20 group-hover:scale-110 transition-transform">BW</div>
                    <div>
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Bank Windhoek</div>
                      <div className="text-sm font-black text-blue-400">Easy Wallet</div>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 bg-white/5 border border-white/10 p-4 rounded-2xl transition-all hover:bg-white/10 group cursor-default">
                    <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center font-black text-xs text-white shadow-lg shadow-indigo-500/20 group-hover:scale-110 transition-transform">SB</div>
                    <div>
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Standard Bank</div>
                      <div className="text-sm font-black text-indigo-400">Blue Wallet</div>
                    </div>
                  </div>
                </div>

                <div className="bg-gradient-to-br from-indigo-500/10 to-blue-500/10 border border-blue-500/30 p-6 rounded-3xl text-center">
                  <p className="text-[10px] font-black bg-gradient-to-r from-amber-300 via-orange-400 to-rose-400 bg-clip-text text-transparent uppercase tracking-[0.3em] mb-2">Activation Hotline</p>
                  <p className="text-2xl font-black text-white tracking-tighter">0813879841</p>
                  <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-3 leading-relaxed">Call for payment and approval</p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // 3. Level Selection
  if (!selectedLevel) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        <BackgroundBlobs />
        {currentUser.isAdmin && (
          <button onClick={() => setIsAdminPanelOpen(true)} className="absolute top-8 left-8 bg-slate-950 text-white px-8 py-4 rounded-3xl text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl hover:scale-110 transition-all z-20 border border-white/10 hover:bg-emerald-600">Admin Dashboard</button>
        )}
        <div className="max-w-5xl w-full text-center relative z-10">
          <header className="mb-20 animate-in fade-in slide-in-from-top-10 duration-1000">
            <div className="flex justify-center mb-8">
              <button onClick={logout} className="glass px-10 py-3 rounded-full shadow-lg text-[11px] font-black text-slate-400 hover:text-red-500 transition-all uppercase tracking-[0.2em] border border-white">Sign Out Protocol</button>
            </div>
            <h1 className="text-6xl md:text-8xl font-black mb-8 tracking-tighter leading-none">
               <span className="bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent">Namibia</span>
               {' '}
               <span className="bg-gradient-to-r from-emerald-600 via-teal-600 to-cyan-600 bg-clip-text text-transparent">Academy</span>
               <br/>
               <span className="bg-gradient-to-r from-amber-500 via-orange-600 to-rose-600 bg-clip-text text-transparent">Pocket</span>
               {' '}
               <span className="bg-gradient-to-r from-slate-900 via-slate-700 to-slate-900 bg-clip-text text-transparent">Tutor</span>
            </h1>
            <p className="text-2xl md:text-3xl font-bold max-w-3xl mx-auto leading-relaxed">
               <span className="bg-gradient-to-r from-indigo-600 to-blue-600 bg-clip-text text-transparent">Welcome back, {currentUser.name}.</span>
               <br/>
               <span className="bg-gradient-to-r from-slate-900 to-slate-500 bg-clip-text text-transparent">Define your current mastery objective.</span>
            </p>
          </header>

          <div className="flex flex-col sm:flex-row gap-10 justify-center items-stretch">
            <button
              onClick={() => setSelectedLevel('NSSCAS')}
              className="group bg-white p-14 rounded-[4rem] shadow-2xl hover:shadow-[0_40px_80px_rgba(37,99,235,0.15)] border border-slate-100 transition-all w-full sm:w-96 flex flex-col items-center hover:scale-105 active:scale-95"
            >
              <div className="bg-gradient-to-br from-blue-600 via-blue-700 to-indigo-800 text-white w-24 h-24 rounded-[2rem] flex items-center justify-center text-5xl mb-10 group-hover:scale-125 transition-transform shadow-2xl shadow-blue-300">AS</div>
              <h3 className="text-4xl font-black bg-gradient-to-r from-blue-700 to-indigo-900 bg-clip-text text-transparent mb-3">NSSCAS</h3>
              <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">Advanced Subsidiary (Grade 12)</p>
            </button>
