              <div className={`max-w-[88%] rounded-[3rem] px-8 py-7 shadow-2xl relative border border-white/50 ${msg.role === 'user' ? 'bg-gradient-to-br from-indigo-600 via-blue-700 to-slate-900 text-white rounded-tr-none' : 'bg-white/90 backdrop-blur-xl text-slate-800 rounded-tl-none'}`}>
                <div className="prose prose-sm max-w-none font-bold text-base leading-relaxed">
                  {msg.content.split('\n').map((line, i) => (<p key={i} className={i > 0 ? 'mt-4' : ''}>{line}</p>))}
                </div>

                {msg.groundingChunks && msg.groundingChunks.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-slate-100 flex flex-wrap gap-2">
                    {msg.groundingChunks.map((chunk, i) => chunk.web && chunk.web.uri && (
                      <a key={i} href={chunk.web.uri} target="_blank" rel="noopener noreferrer" className="text-[10px] font-black bg-white text-slate-700 px-4 py-2 rounded-xl hover:bg-gradient-to-r hover:from-blue-600 hover:to-purple-600 hover:text-white transition-all border border-slate-100 shadow-sm flex items-center gap-2 group/source">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 text-indigo-500 group-hover/source:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                        {chunk.web.title || 'Source'}
                      </a>
                    ))}
                  </div>
                )}

                <div className="flex items-center justify-between mt-5 text-[10px] font-black uppercase tracking-widest">
                  <span className={msg.role === 'user' ? 'opacity-60 text-white' : 'bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent'}>
                    {msg.role === 'user' ? currentUser?.name : `AI ${selectedSubject.id} SPECIALIST`}
                  </span>
                  <span className={msg.role === 'user' ? 'opacity-40 text-white' : 'opacity-40 text-slate-400'}>
                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            </div>
          ))}

          {isTyping && (
            <div className="flex justify-start">
              <div className="bg-white/50 backdrop-blur-md rounded-[2.5rem] rounded-tl-none px-8 py-6 shadow-xl border border-white">
                <div className="flex gap-2">
                  <span className="w-2.5 h-2.5 bg-blue-500 rounded-full animate-bounce"></span>
                  <span className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-2.5 h-2.5 bg-purple-500 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            </div>
          )}

          {isVoiceActive && !statusMessage && (
            <div className="text-center py-16 animate-in fade-in zoom-in duration-500">
              <div className="inline-flex flex-col items-center">
                 <div className="relative mb-10">
                   <div className="absolute inset-0 bg-blue-500 rounded-full animate-ping opacity-20 duration-[2s]"></div>
                   <div className="absolute inset-0 bg-indigo-500 rounded-full animate-ping opacity-20 delay-500 duration-[2.5s]"></div>
                   <div className="bg-slate-950 p-12 rounded-[3.5rem] text-white shadow-3xl relative">
                     <svg xmlns="http://www.w3.org/2000/svg" className="h-14 w-14 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                       <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                     </svg>
                   </div>
                 </div>
                 <h4 className="font-black bg-gradient-to-r from-blue-700 via-indigo-700 to-purple-700 bg-clip-text text-transparent text-sm uppercase tracking-[0.4em]">Audio Logic Node</h4>
                 <p className="bg-gradient-to-r from-emerald-600 to-teal-600 bg-clip-text text-transparent font-black text-[11px] mt-3 uppercase tracking-widest">Actively listening to reasoning cycles...</p>
              </div>
            </div>
          )}
        </div>
      </main>

      <footer className="glass border-t border-white px-8 py-8 sticky bottom-0 z-20 backdrop-blur-2xl shadow-[0_-20px_50px_rgba(0,0,0,0.05)]">
        <div className="max-w-4xl mx-auto">
          <div className="flex gap-6 items-center">
            <button 
              onClick={isVoiceActive ? stopVoiceMode : startVoiceMode} 
              className={`p-6 rounded-[2.2rem] transition-all shadow-2xl flex items-center justify-center hover:scale-110 active:scale-90 ${isVoiceActive ? 'bg-gradient-to-br from-rose-500 to-pink-600 text-white animate-pulse' : 'bg-slate-950 text-white'}`}
            >
              {isVoiceActive ? <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg> : <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>}
            </button>
            <form onSubmit={handleSendMessage} className="relative flex-grow flex items-center">
              <input 
                type="text" 
                value={inputValue} 
                onChange={(e) => setInputValue(e.target.value)} 
                placeholder={isVoiceActive ? "Neural audio link established..." : "Contribute your reasoning here..."} 
                className="w-full bg-white/70 border border-slate-200 rounded-[2.2rem] pl-8 pr-20 py-6 focus:ring-[12px] focus:ring-indigo-100 outline-none font-black text-slate-800 transition-all shadow-lg placeholder:text-slate-400" 
                disabled={isTyping || isVoiceActive} 
              />
              <button 
                type="submit" 
                disabled={isTyping || isVoiceActive || !inputValue.trim()} 
                className={`absolute right-3.5 p-4 rounded-[1.5rem] transition-all ${!inputValue.trim() || isTyping || isVoiceActive ? 'text-slate-300 bg-transparent' : 'bg-gradient-to-br from-indigo-600 via-purple-700 to-rose-700 text-white shadow-xl hover:scale-105 active:scale-95'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" viewBox="0 0 20 20" fill="currentColor">
                  <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
                </svg>
              </button>
            </form>
          </div>
          <div className="flex justify-between items-center mt-6 px-6">
            <p className="text-[11px] font-black bg-gradient-to-r from-slate-400 to-slate-600 bg-clip-text text-transparent uppercase tracking-[0.3em]">Neural Socratic Tutor 1.0</p>
            <p className="text-[11px] font-black bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent uppercase tracking-[0.3em] animate-pulse">Quantum Achieving Node</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { Subject, Level } from "../types";

const getSystemInstruction = (subject: Subject, level: Level) => `
    Expert ${level} Tutor for ${subject}.
    - Follow Socratic Method: Ask ONE question at a time.
    - No direct answers. Build reasoning.
    - Use Namibian analogies.
    - Treat conversation as fresh/anonymous.
    - IMPORTANT: Include simple but informative illustrations using well-structured ASCII art or text-based diagrams when explaining concepts. These should look like powerful, clear hand-drawn sketches to help visualize the topic.
`.trim();

export const createChatInstance = (subject: Subject, level: Level) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: getSystemInstruction(subject, level),
      temperature: 0.7,
      tools: [{ googleSearch: {} }]
    },
  });
};

export const connectTutorLive = (
  subject: Subject, 
  level: Level, 
  callbacks: {
    onopen: () => void;
    onmessage: (message: LiveServerMessage) => void;
    onerror: (e: ErrorEvent) => void;
    onclose: (e: CloseEvent) => void;
  }
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks,
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } },
      },
      systemInstruction: getSystemInstruction(subject, level),
    },
  });
};

