      setMessages(prev => [...prev, { id: 'err', role: 'assistant', content: "Neural link disruption. Please retry.", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  const exportSession = () => {
    if (!selectedSubject || messages.length === 0) return;
    const htmlContent = `
      <!DOCTYPE html>
      <html lang="en">
      <head>
