const App: React.FC = () => {
  // --- Auth & User State ---
  const [allUsers, setAllUsers] = useState<AppUser[]>(() => {
    const saved = localStorage.getItem('pocket_tutor_users');
    return saved ? JSON.parse(saved) : [];
  });
  const [currentUser, setCurrentUser] = useState<AppUser | null>(() => {
    const saved = localStorage.getItem('pocket_tutor_session');
    return saved ? JSON.parse(saved) : null;
  });
  const [authView, setAuthView] = useState<'login' | 'signup' | 'admin_login'>('login');
  const [authError, setAuthError] = useState<string | null>(null);
  const [authSuccess, setAuthSuccess] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [isAdminPanelOpen, setIsAdminPanelOpen] = useState(false);

  // Form Fields
  const [nameField, setNameField] = useState('');
  const [phoneField, setPhoneField] = useState('');
  const [emailField, setEmailField] = useState('');
  const [passwordField, setPasswordField] = useState('');

  // --- App Flow State ---
  const [selectedLevel, setSelectedLevel] = useState<Level | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<SubjectOption | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isVoiceActive, setIsVoiceActive] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  // --- Refs ---
  const chatRef = useRef<Chat | null>(null);
  const liveSessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // --- Persistence ---
  useEffect(() => { localStorage.setItem('pocket_tutor_users', JSON.stringify(allUsers)); }, [allUsers]);
  useEffect(() => {
    if (currentUser) localStorage.setItem('pocket_tutor_session', JSON.stringify(currentUser));
    else localStorage.removeItem('pocket_tutor_session');
  }, [currentUser]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isTyping, isVoiceActive]);

  // --- Handlers ---
  const handleSignUp = (e: React.FormEvent) => {
    e.preventDefault();
    if (allUsers.find(u => u.phone === phoneField)) { setAuthError("Phone already registered."); return; }
    const newUser: AppUser = { id: Date.now().toString(), name: nameField, phone: phoneField, password: passwordField, status: 'pending' };
    setAllUsers([...allUsers, newUser]);
    setAuthSuccess("Enrollment received! Awaiting approval.");
    setAuthView('login');
    setNameField(''); setPhoneField(''); setPasswordField('');
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = allUsers.find(u => u.phone === phoneField && u.password === passwordField);
    if (!user) { setAuthError("Invalid credentials."); return; }
    if (user.status !== 'approved') { setAuthError(`Access ${user.status}. Contact 0813879841.`); return; }
    setCurrentUser(user);
    setPhoneField(''); setPasswordField('');
  };

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (emailField === ADMIN_EMAIL && passwordField === ADMIN_PASSWORD) {
      const admin: AppUser = { id: 'admin', name: 'Admin', phone: 'SYSTEM', status: 'approved', isAdmin: true, password: ADMIN_PASSWORD };
      setCurrentUser(admin); setIsAdminPanelOpen(true);
    } else { setAuthError("Access Denied."); }
  };

  const logout = () => { setCurrentUser(null); setIsAdminPanelOpen(false); resetChat(); };

  const stopVoiceMode = useCallback(() => {
    if (liveSessionRef.current) { liveSessionRef.current.then((s: any) => s.close()); liveSessionRef.current = null; }
    if (inputAudioContextRef.current) { inputAudioContextRef.current.close(); inputAudioContextRef.current = null; }
    if (outputAudioContextRef.current) { outputAudioContextRef.current.close(); outputAudioContextRef.current = null; }
    sourcesRef.current.forEach(s => s.stop()); sourcesRef.current.clear();
    setIsVoiceActive(false); setStatusMessage(null);
  }, []);

  const startVoiceMode = async () => {
    if (!selectedSubject) return;
    setIsVoiceActive(true); setStatusMessage("Linking Neural Audio...");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      inputAudioContextRef.current = inputCtx; outputAudioContextRef.current = outputCtx;

      const sessionPromise = connectTutorLive(selectedSubject.id, selectedSubject.level, {
        onopen: () => {
          setStatusMessage(null);
          const source = inputCtx.createMediaStreamSource(stream);
          const processor = inputCtx.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const data = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(data.length);
            for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({ media: { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } }));
          };
          source.connect(processor); processor.connect(inputCtx.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (audio && outputAudioContextRef.current) {
            const ctx = outputAudioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const buf = await decodeAudioData(decode(audio), ctx, 24000, 1);
            const src = ctx.createBufferSource(); src.buffer = buf; src.connect(ctx.destination);
            src.start(nextStartTimeRef.current); nextStartTimeRef.current += buf.duration;
            sourcesRef.current.add(src); src.onended = () => sourcesRef.current.delete(src);
          }
        },
        onerror: stopVoiceMode, onclose: stopVoiceMode
      });
      liveSessionRef.current = sessionPromise;
    } catch { stopVoiceMode(); setStatusMessage("Mic Error."); }
  };

  const selectSubject = (s: SubjectOption) => {
    setSelectedSubject(s);
    chatRef.current = createChatInstance(s.id, s.level);
    setMessages([{ id: 'g', role: 'assistant', content: `Greetings, Scholar ${currentUser?.name}. I am your ${s.id} specialist for the 2026 ${selectedLevel} curriculum. What shall we explore?`, timestamp: new Date() }]);
  };

  const resetChat = () => { stopVoiceMode(); setSelectedSubject(null); setMessages([]); chatRef.current = null; };

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isTyping || !chatRef.current) return;
    const msg = inputValue; setInputValue('');
    setMessages(prev => [...prev, { id: Date.now().toString(), role: 'user', content: msg, timestamp: new Date() }]);
    setIsTyping(true);
    try {
      const res = await chatRef.current.sendMessage({ message: msg });
      setMessages(prev => [...prev, { 
        id: 'a'+Date.now(), 
        role: 'assistant', 
        content: res.text || "Reasoning processed according to 2026 syllabus standards. Let's move to the next stage.", 
        timestamp: new Date(),
        groundingChunks: res.candidates?.[0]?.groundingMetadata?.groundingChunks as any
      }]);
    } catch (error) {
      setMessages(prev => [...prev, { id: 'err', role: 'assistant', content: "Neural link disruption. Please retry.", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  const exportSession = () => {
    if (!selectedSubject || messages.length === 0) return;
    const htmlContent = `
      <!DOCTYPE html>
      <html lang="en">
      <head>
        <meta charset="UTF-8">
        <title>Pocket Tutor Session Log - ${selectedSubject.id} (2026 Curriculum)</title>
        <style>
          body { 
            font-family: "Times New Roman", Times, serif; 
            padding: 50px; 
            line-height: 1.6; 
            max-width: 800px; 
            margin: auto; 
            color: #1a1a1a;
          }
          h1 { border-bottom: 2px solid #333; padding-bottom: 10px; margin-bottom: 30px; }
          .meta { margin-bottom: 40px; font-style: italic; color: #555; }
          .message { margin-bottom: 30px; }
          .role { font-weight: bold; text-transform: uppercase; display: block; margin-bottom: 5px; color: #000; }
          .timestamp { font-size: 0.85em; color: #888; margin-left: 10px; font-weight: normal; }
          .content { background: #fdfdfd; padding: 10px; border-left: 3px solid #ccc; white-space: pre-wrap; }
        </style>
      </head>
      <body>
        <h1>NAMIBIAN ACADEMY SESSION LOG (2026)</h1>
        <div class="meta">
          <p><strong>Level:</strong> ${selectedLevel}</p>
          <p><strong>Subject:</strong> ${selectedSubject.id}</p>
          <p><strong>Student:</strong> ${currentUser?.name}</p>
          <p><strong>Date:</strong> ${new Date().toLocaleString()}</p>
        </div>
        ${messages.map(msg => `
          <div class="message">
            <span class="role">${msg.role === 'user' ? 'STUDENT' : 'TUTOR'} <span class="timestamp">${msg.timestamp.toLocaleString()}</span></span>
            <div class="content">${msg.content}</div>
          </div>
        `).join('')}
      </body>
      </html>
    `;
    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Academy_Session_2026_${selectedSubject.id}_${Date.now()}.html`;
    link.click();
    URL.revokeObjectURL(url);
  };

  // --- Breadcrumb Navigation ---
  const NavBreadcrumbs = () => {
    if (!currentUser) return null;
    return (
      <div className="flex items-center gap-2 px-8 py-3 bg-white/50 backdrop-blur-md border-b border-white/20 sticky top-0 z-50 text-[10px] font-black uppercase tracking-widest text-slate-500">
        <button onClick={() => { setSelectedLevel(null); resetChat(); }} className="hover:text-blue-600 transition-colors">Academy Root</button>
        {selectedLevel && (
          <>
            <span>/</span>
            <button onClick={() => resetChat()} className={`hover:text-blue-600 transition-colors ${!selectedSubject ? 'text-slate-900' : ''}`}>
              {selectedLevel} (2026 Curriculum)
            </button>
          </>
        )}
        {selectedSubject && (
          <>
            <span>/</span>
            <span className="text-slate-900">{selectedSubject.id}</span>
          </>
        )}
      </div>
    );
  };

  const filteredSubjects = SUBJECTS.filter(s => s.level === selectedLevel && (searchQuery === '' || s.id.toLowerCase().includes(searchQuery.toLowerCase())));

  // --- VIEWS ---

  if (currentUser?.isAdmin && isAdminPanelOpen) {
    return (
      <div className="min-h-screen bg-slate-950 text-white p-8 overflow-y-auto relative">
        <BackgroundBlobs />
        <div className="max-w-6xl mx-auto relative z-10">
          <header className="flex justify-between items-center mb-12">
            <h1 className="text-4xl font-black bg-gradient-to-r from-emerald-400 to-cyan-400 bg-clip-text text-transparent">Admin Command</h1>
            <div className="flex gap-4">
              <button onClick={() => setIsAdminPanelOpen(false)} className="glass px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest">App View</button>
              <button onClick={logout} className="bg-red-500/20 text-red-500 px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest">Logout</button>
            </div>
          </header>
          <div className="glass rounded-3xl p-8 border border-white/10">
             <table className="w-full text-left">
               <thead>
                 <tr className="border-b border-white/10 text-slate-500 text-[10px] uppercase font-black">
                   <th className="py-4">Student</th>
                   <th className="py-4">Phone</th>
                   <th className="py-4">Status</th>
                   <th className="py-4 text-right">Actions</th>
                 </tr>
               </thead>
               <tbody>
                 {allUsers.map(u => (
                   <tr key={u.id} className="border-b border-white/5 hover:bg-white/5 transition-colors">
                     <td className="py-4 font-bold">{u.name}</td>
                     <td className="py-4 text-slate-400">{u.phone}</td>
                     <td className="py-4">
                        <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase ${u.status === 'approved' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-amber-500/20 text-amber-400'}`}>{u.status}</span>
                     </td>
                     <td className="py-4 text-right">
                        {u.status === 'pending' && <button onClick={() => setAllUsers(allUsers.map(usr => usr.id === u.id ? {...usr, status: 'approved'} : usr))} className="bg-emerald-500 text-white px-4 py-1.5 rounded-lg text-[10px] font-black uppercase">Approve</button>}
                        {u.status === 'approved' && <button onClick={() => setAllUsers(allUsers.map(usr => usr.id === u.id ? {...usr, status: 'revoked'} : usr))} className="bg-red-500/20 text-red-500 px-4 py-1.5 rounded-lg text-[10px] font-black uppercase ml-2">Revoke</button>}
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 relative overflow-hidden">
        <BackgroundBlobs />
        <div className="max-w-md w-full relative z-10">
          <div className="text-center mb-10">
            <h1 className="text-5xl font-black mb-3 tracking-tighter bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent">Pocket Tutor</h1>
            <p className="text-slate-400 font-black text-[10px] uppercase tracking-[0.3em]">2026 Namibian NSSCO/NSSCAS Expert</p>
          </div>
          <div className="glass rounded-[2.5rem] shadow-2xl p-10 border border-white">
            {authSuccess && <div className="bg-emerald-50 text-emerald-600 p-4 rounded-2xl text-xs font-bold mb-6 text-center border border-emerald-100">{authSuccess}</div>}
            {authError && <div className="bg-rose-50 text-red-500 p-4 rounded-2xl text-xs font-bold mb-6 text-center border border-red-100">{authError}</div>}
            <form onSubmit={authView === 'login' ? handleLogin : authView === 'signup' ? handleSignUp : handleAdminLogin} className="space-y-6">
              {authView === 'signup' && (
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase ml-4 text-slate-400">Scholar Name</label>
                  <input type="text" value={nameField} onChange={(e) => setNameField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-indigo-100 outline-none font-bold shadow-sm" />
                </div>
              )}
              {authView === 'admin_login' ? (
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase ml-4 text-slate-400">Admin Identity</label>
                  <input type="email" value={emailField} onChange={(e) => setEmailField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-indigo-100 outline-none font-bold shadow-sm" />
                </div>
              ) : (
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase ml-4 text-slate-400">Phone Node</label>
                  <input type="tel" value={phoneField} onChange={(e) => setPhoneField(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-indigo-100 outline-none font-bold shadow-sm" placeholder="+264 ..." />
                </div>
              )}
              <PasswordInput value={passwordField} onChange={setPasswordField} placeholder="••••••••" label="Mastery Key" showPassword={showPassword} setShowPassword={setShowPassword} />
              <button type="submit" className="w-full bg-slate-950 text-white font-black py-5 rounded-2xl shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all uppercase tracking-[0.2em] text-[11px]">
                {authView === 'login' ? 'Initiate Access' : authView === 'signup' ? 'Request Enrollment' : 'Authorize Node'}
              </button>
            </form>
            <div className="mt-8 pt-8 border-t border-slate-100 flex flex-col gap-4 text-center">
              {authView === 'login' && <button onClick={() => { setAuthView('signup'); setAuthError(null); }} className="text-[10px] font-black text-indigo-600 uppercase tracking-widest hover:underline">Enrollment Required?</button>}
              {(authView === 'signup' || authView === 'admin_login') && <button onClick={() => setAuthView('login')} className="text-[10px] font-black text-indigo-600 uppercase tracking-widest hover:underline">Return to Portal</button>}
              {authView === 'login' && <button onClick={() => setAuthView('admin_login')} className="text-[10px] font-bold text-slate-300 uppercase tracking-[0.3em] hover:text-slate-900 transition-colors">Nexus Master</button>}
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!selectedLevel) {
    return (
      <div className="min-h-screen flex flex-col bg-slate-50 relative overflow-hidden">
        <BackgroundBlobs />
        <NavBreadcrumbs />
        <div className="flex-grow flex items-center justify-center p-6 relative z-10">
          <div className="max-w-4xl w-full text-center">
            <header className="mb-16">
              <h2 className="text-6xl font-black mb-6 tracking-tighter bg-gradient-to-r from-blue-600 to-indigo-800 bg-clip-text text-transparent">Define 2026 Mastery Level</h2>
              <p className="text-slate-400 font-bold uppercase tracking-[0.25em] text-xs">Namibian NIED/NAMCOL Curriculum Standards</p>
            </header>
            <div className="flex flex-col md:flex-row gap-8 justify-center items-stretch">
              <button onClick={() => setSelectedLevel('NSSCAS')} className="group glass p-12 rounded-[3rem] shadow-2xl hover:scale-105 transition-all flex flex-col items-center flex-1 border border-white">
                <div className="bg-indigo-600 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-3xl font-black mb-8 shadow-xl shadow-indigo-200 group-hover:rotate-6 transition-transform">AS</div>
                <h3 className="text-3xl font-black mb-2">NSSCAS</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Advanced Subsidiary (Gr 12) 2026</p>
              </button>
              <button onClick={() => setSelectedLevel('NSSCO')} className="group glass p-12 rounded-[3rem] shadow-2xl hover:scale-105 transition-all flex flex-col items-center flex-1 border border-white">
                <div className="bg-emerald-500 text-white w-20 h-20 rounded-3xl flex items-center justify-center text-3xl font-black mb-8 shadow-xl shadow-emerald-200 group-hover:rotate-6 transition-transform">O</div>
                <h3 className="text-3xl font-black mb-2">NSSCO</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Ordinary Level (Gr 10-11) 2026</p>
              </button>
            </div>
            <button onClick={logout} className="mt-16 text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] hover:text-red-500 transition-colors">Terminate Node</button>
          </div>
