        <NavBreadcrumbs />
        <div className="flex-grow max-w-7xl mx-auto py-16 px-8 relative z-10 w-full">
          <header className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-8">
            <div>
              <h2 className="text-5xl font-black mb-2 tracking-tighter text-slate-900">{selectedLevel} 2026 Syllabus</h2>
              <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Syllabus-aligned tutoring with search-enabled past papers</p>
